/// The `record_tag` wire protocol (GOAL #2394, Compaction 2.0 v2.1).
///
/// Every visible session record rides the wire prefixed with its file
/// alias — `m<seq> ` (`m142 toolResult(bash): …`) — so the model can
/// ADDRESS records in a hand-over reply ("hide 142-143") and the engine
/// can resolve those numbers back to stable record ids through the
/// SNAPSHOT index of the request the model actually saw.
///
/// Invariants (I4):
/// - a tag is wire-only: it is stamped on a COPY of the transcript right
///   before the request transforms, never on the transcript itself, never
///   persisted (`Context.toJson` is untouched);
/// - inside a tag epoch (the projection the transcript was rebuilt from)
///   the head messages carry their exact alias and the bytes are stable;
///   messages appended after the epoch started (the run's live edge —
///   the prompt, nudges, this run's answers and tool results) carry NO
///   tag: they are not records of this epoch yet (persistence is
///   asynchronous) and the model does not address them. The next epoch
///   (the next run's projection rebuild) tags them — one uncached
///   segment at the run boundary (E30), visible in the main request's
///   cache metric and the accepted conservative default of the card;
/// - non-records (the obligations / working-set tail blocks, `time-left:`
///   lines, carrier pins, the hand-over instruction) never carry a tag;
/// - tags exist only under the structured engine (`compaction.engine`).
///
/// Pure Dart — no IO; the transcript seq map is built by the session
/// projection (`Session.buildTranscriptProjection`).
library;

import '../context.dart';
import '../types.dart';
import 'structured/projection.dart' show RecordSeqIndex;

/// The pressure-basis cost of one record tag: `m142 ` is 2 tiktoken
/// tokens (o200k) and ≤ 5 for six-digit aliases — the budget pinned for
/// the `tagOverhead` term of the request estimate (D14).
const int recordTagTokens = 5;

/// The maximum alias the 5-token budget covers (`m999999 `).
const int _recordTagMaxSeq = 999999;

final RegExp _recordTagLineStart = RegExp(r'^m(\d+) ');
final RegExp _recordTagEchoLines = RegExp(r'^m\d+ +', multiLine: true);

/// The wire form of record [seq]: `m<seq>`.
String recordTag(int seq) => 'm$seq';

/// The seq a [text] opens with (`m142 rest` → 142), else `null`.
int? leadingRecordTag(String text) {
  final match = _recordTagLineStart.firstMatch(text);
  if (match == null) return null;
  final seq = int.tryParse(match.group(1)!);
  return seq != null && seq > 0 && seq <= _recordTagMaxSeq ? seq : null;
}

/// Whether [text] opens with a record tag (a tagged record line).
bool hasRecordTag(String text) => leadingRecordTag(text) != null;

/// Whether [message] is a record copy whose first text block opens with a
/// tag (the stamping is idempotent: a tagged copy is returned as is).
bool messageHasRecordTag(Message message) =>
    leadingRecordTag(firstTextOf(message)) != null;

/// The text of [message]'s first text block ('' when it has none).
String firstTextOf(Message message) {
  final blocks = messageBlocks(message);
  for (final block in blocks) {
    if (block is TextContent) return block.text;
  }
  return '';
}

/// The content blocks of [message] (a plain-string user message is a
/// one-text-block list; unknown shapes fold to empty).
List<ContentBlock> messageBlocks(Message message) => switch (message) {
  UserMessage(:final content) when content is List => [
    for (final block in content) block,
  ],
  UserMessage(:final content) => [TextContent(text: content as String)],
  ToolResultMessage(:final content) => content,
  AssistantMessage(:final content) => content,
  _ => const [],
};

/// Removes every leading `m<N> ` tag from the start of [text]'s lines —
/// the persist-side echo hygiene (E16): a hand-over text that repeated
/// the wire tags carries none once stored.
String stripRecordTags(String text) => text.replaceAll(_recordTagEchoLines, '');

/// One transcript build: the projected messages plus the record alias each
/// message projects from (aligned by index, `null` = a non-record) and
/// the file-order index the aliases resolve against — the tag epoch the
/// agent stamps requests from.
final class TranscriptProjection {
  /// Creates the projection; [recordSeqs] runs parallel to [messages].
  const TranscriptProjection({
    required this.messages,
    required this.recordSeqs,
    required this.index,
  });

  /// The projected transcript (`buildContextMessages` output).
  final List<Message> messages;

  /// The record alias per message, aligned by index (`null` = non-record).
  final List<int?> recordSeqs;

  /// The file-order record index the aliases resolve against.
  final RecordSeqIndex index;

  /// The tag epoch over this projection.
  TranscriptSeqMap get seqMap =>
      TranscriptSeqMap(headSeqs: recordSeqs, index: index);
}

/// The aligned record aliases of a transcript plus the epoch index they
/// resolve against — `null` marks a non-record (level-0 tail blocks,
/// instructions, notices) AND the live edge (messages appended since the
/// epoch started: untaged until the next epoch).
final class TranscriptSeqMap {
  /// Creates the map of one tag epoch: [headSeqs] aligned to the
  /// projected transcript head, [index] the epoch's file-order snapshot.
  const TranscriptSeqMap({required this.headSeqs, required this.index});

  /// The seqs of the projected head, aligned by message index (`null` =
  /// a non-record). Treated as read-only by every consumer.
  final List<int?> headSeqs;

  /// The epoch's record index (seq → record). Frozen at epoch start: an
  /// id beyond it never resolves, so a mis-predicted live-edge alias
  /// cannot hide someone else's record.
  final RecordSeqIndex index;

  /// Number of head messages (the projected transcript at epoch start).
  int get headLength => headSeqs.length;

  /// The alias of the message at [position]: exact on the head (the
  /// epoch's records), `null` beyond it — the live edge carries no tag
  /// (the epoch rule: a message becomes addressable when the NEXT epoch's
  /// projection makes it a record) — and `null` for a non-record.
  int? seqAt(int position) {
    if (position < 0 || position >= headSeqs.length) return null;
    return headSeqs[position];
  }

  /// The stable record id the alias at [position] resolves to on the
  /// epoch index — `null` for non-records, the live edge and unknown
  /// aliases.
  String? recordIdAt(int position) {
    final seq = seqAt(position);
    if (seq == null) return null;
    final record = index.recordAt(seq);
    return record?.id;
  }

  /// The seqs of a [length]-message transcript, aligned by index.
  List<int?> seqsFor(int length) => [for (var i = 0; i < length; i++) seqAt(i)];
}

/// The tag budget of [taggedRecords] tagged messages (the `tagOverhead`
/// term of the request estimate).
int tagOverheadTokens(int taggedRecords) =>
    taggedRecords <= 0 ? 0 : taggedRecords * recordTagTokens;

/// How many messages in [seqs] are tagged records — all of them without a
/// usage anchor, only the ones AFTER the anchor with one (the anchor's
/// reported usage already priced the tags of everything up to it).
int taggedRecordCount(List<int?> seqs, {int? after}) {
  var count = 0;
  for (var i = 0; i < seqs.length; i++) {
    if (seqs[i] != null && (after == null || i > after)) count++;
  }
  return count;
}

/// Stamps record tags on a COPY of [messages]: every message whose aligned
/// seq is non-null gets `m<seq> ` in its first text block; non-records and
/// a `null` map pass through UNTOUCHED (the untagged transcript, the same
/// list). The transcript itself is never modified (I4).
List<Message> tagTranscript(List<Message> messages, TranscriptSeqMap? seqMap) {
  if (seqMap == null || messages.isEmpty) return messages;
  final tagged = <Message>[];
  var changed = false;
  for (var i = 0; i < messages.length; i++) {
    final seq = seqMap.seqAt(i);
    final message = messages[i];
    if (seq == null || messageHasRecordTag(message)) {
      tagged.add(message);
      continue;
    }
    final copy = tagRecordMessage(message, seq);
    changed = true;
    tagged.add(copy);
  }
  return changed ? tagged : messages;
}

/// [tagTranscript] over a request [Context]: the system prompt and tools
/// ride byte-identically, only the message copies carry tags.
Context tagContext(Context context, TranscriptSeqMap? seqMap) {
  if (seqMap == null) return context;
  final tagged = tagTranscript(context.messages, seqMap);
  if (identical(tagged, context.messages)) return context;
  return Context(
    systemPrompt: context.systemPrompt,
    messages: tagged,
    tools: context.tools,
  );
}

/// The tagged copy of one record [message]: the tag goes into the first
/// text block — for an assistant message, the first text block AFTER its
/// leading thinking blocks (signed thinking keeps its position and
/// order; the tag never lands before it). A record with no text block
/// (a pure tool-call carrier, an image-only record) gets a new first
/// text block holding the tag alone (plus `image/<mime>` for images) —
/// image parts are never touched (E17, E18).
Message tagRecordMessage(Message message, int seq) {
  final tag = recordTag(seq);
  switch (message) {
    case UserMessage(:final content, :final timestamp):
      if (content is String) {
        return UserMessage(
          content: _tagText(content, tag),
          timestamp: timestamp,
        );
      }
      return UserMessage(
        content: _tagBlocks(content as List<ContentBlock>, tag),
        timestamp: timestamp,
      );
    case ToolResultMessage(
      :final toolCallId,
      :final toolName,
      :final content,
      :final isError,
      :final timestamp,
    ):
      return ToolResultMessage(
        toolCallId: toolCallId,
        toolName: toolName,
        content: _tagBlocks(content, tag),
        isError: isError,
        timestamp: timestamp,
      );
    case AssistantMessage(:final content):
      return message.copyWith(content: _tagAssistantBlocks(content, tag));
    default:
      return message;
  }
}

String _tagText(String text, String tag) =>
    hasRecordTag(text) ? text : '$tag $text';

String _tagBlocksText(String text, String tag) => '$tag $text';

List<ContentBlock> _tagBlocks(List<ContentBlock> blocks, String tag) {
  for (var i = 0; i < blocks.length; i++) {
    final block = blocks[i];
    if (block is TextContent) {
      if (hasRecordTag(block.text)) return blocks;
      return [
        for (var j = 0; j < blocks.length; j++)
          if (j == i)
            block.copyWith(text: _tagBlocksText(block.text, tag))
          else
            blocks[j],
      ];
    }
  }
  // No text block: a tag-only block in front (image parts untouched).
  final image = blocks.whereType<ImageContent>().firstOrNull;
  final label = image == null ? tag : '$tag image/${image.mimeType}';
  return [TextContent(text: label), ...blocks];
}

List<ContentBlock> _tagAssistantBlocks(List<ContentBlock> blocks, String tag) {
  var index = 0;
  while (index < blocks.length && blocks[index] is ThinkingContent) {
    index++;
  }
  for (var i = index; i < blocks.length; i++) {
    final block = blocks[i];
    if (block is TextContent) {
      if (hasRecordTag(block.text)) return blocks;
      return [
        for (var j = 0; j < blocks.length; j++)
          if (j == i)
            block.copyWith(text: _tagBlocksText(block.text, tag))
          else
            blocks[j],
      ];
    }
  }
  // Pure tool-call carrier: a tag-only text block after the thinking
  // blocks (never before signed thinking).
  return [...blocks.take(index), TextContent(text: tag), ...blocks.skip(index)];
}

/// `RequestSnapshot` (S0) — the last MAIN request "as sent" (GOAL #2394).
///
/// The hand-over call reads the exact prefix the session just warmed:
/// system prompt, tools and the message list of the last main send, plus
/// the record index the request's `m<seq>` tags resolve against. Every
/// main send overwrites the snapshot (last wins — the degenerate-empty
/// retry streams the same context); a snapshot is INVALID once it no
/// longer describes the live context:
///
/// - the session model changed (`prepareNextTurn` switched models — the
///   prefix a different model cached is nobody's warm bucket);
/// - a compaction run succeeded (the projection changed);
/// - the host switched branches / restored a checkpoint (the projection
///   was replaced — hosts call [RequestSnapshotStore.invalidate]).
///
/// A failed compaction run leaves the snapshot valid (nothing was
/// appended). S0 is a `Context`, not wire bytes: adapters rewrite the
/// payload — byte-identity of the prefix is asserted on the payload the
/// adapter serializes (`onPayload`), for the same model and compat.
///
/// Pure Dart — no IO.
library;

import '../context.dart';
import '../model.dart';
import '../types.dart';
import 'record_tag.dart';

/// How long a snapshot's cache bucket counts as warm (the report's
/// `bucket` signal — never a mode condition): Anthropic ephemeral
/// breakpoints and OpenAI prefix caches live ~5 minutes.
const Duration requestSnapshotBucketTtl = Duration(minutes: 5);

/// Whether [a] and [b] are the same served model (provider + id + base
/// URL) — the identity a snapshot's warm bucket is keyed by.
bool sameServedModel(Model a, Model b) =>
    a.provider == b.provider && a.id == b.id && a.baseUrl == b.baseUrl;

/// The last main request as sent. Immutable; [messages] is a private copy.
final class RequestSnapshot {
  /// Creates a snapshot; [messages] is copied, [seqMap] is the epoch the
  /// request's tags were stamped from.
  RequestSnapshot({
    required this.model,
    required List<Message> messages,
    this.systemPrompt,
    List<Tool> tools = const [],
    required this.seqMap,
    required this.sentAt,
    this.routing,
  }) : messages = List.unmodifiable(messages),
       tools = List.unmodifiable(tools);

  /// The model that served the request (`config.model` at send time —
  /// `prepareNextTurn` may have switched it away from the state model).
  final Model model;

  /// The request messages exactly as sent (post-transform — `time-left:`
  /// lines, pin carriers, pairing repairs included).
  final List<Message> messages;

  /// The request's system prompt.
  final String? systemPrompt;

  /// The request's tool manifest.
  final List<Tool> tools;

  /// The tag epoch the request was stamped from: seq → record resolution
  /// for the hand-over reply's hide list happens against THIS frozen
  /// index, never a fresh ledger (aliases drift under windowed storage
  /// and hard caps; the live edge — untaged — never names an alias).
  final TranscriptSeqMap seqMap;

  /// When the request was handed to the provider stream.
  final DateTime sentAt;

  /// The routing values the request rode (zone overrides), when any.
  final RequestRouting? routing;

  /// Whether this snapshot still describes the context [current] would
  /// send next: same served model.
  bool isValidFor(Model current) => sameServedModel(model, current);

  /// `warm` while the provider cache bucket the request wrote is still
  /// alive ([requestSnapshotBucketTtl]), else `cold` — a report signal.
  String bucket({DateTime? now}) =>
      (now ?? DateTime.now()).difference(sentAt) <= requestSnapshotBucketTtl
      ? 'warm'
      : 'cold';

  /// The stable record id behind alias [seq] on the frozen epoch index —
  /// `null` for unknown aliases (beyond the index, non-positive) and for
  /// records that never project into the model context (the hidden-range
  /// and pin bookkeeping records themselves).
  String? recordIdAt(int seq) {
    if (seq <= 0) return null;
    final record = seqMap.index.recordAt(seq);
    return record?.id;
  }

  /// The snapshot as the request context the hand-over call extends: a
  /// fresh `Context` over the stored copies (callers append their
  /// instruction to a COPY of the list).
  Context toContext({List<Message> extraMessages = const []}) => Context(
    systemPrompt: systemPrompt,
    messages: [...messages, ...extraMessages],
    tools: tools.isEmpty ? null : tools,
  );

  /// The prefix message count — the history breakpoint position the
  /// hand-over call passes to adapters that support `prefixLength` (the
  /// breakpoint sits on S0's last message, not on the instruction).
  int get prefixLength => messages.length;
}

/// The routing values a request rode.
final class RequestRouting {
  /// Creates the routing record.
  const RequestRouting({this.sessionId, this.cacheRetention});

  /// The prompt-cache affinity id (null = the provider default resolved
  /// at call time).
  final String? sessionId;

  /// The cache retention (`short`/`long`/`none`; null = provider default).
  final String? cacheRetention;
}

/// Last-wins holder of the session's [RequestSnapshot] — ONE per agent,
/// written at the main-send seam, read by the compaction host.
final class RequestSnapshotStore {
  RequestSnapshot? _snapshot;
  String? _invalidReason;

  /// The current snapshot, valid or not (hosts render its state).
  RequestSnapshot? get current => _snapshot;

  /// Why the last snapshot was invalidated, when a host/compaction run
  /// did it explicitly (model switches report through [validFor]).
  String? get invalidReason => _invalidReason;

  /// Records the latest main send (last wins, clears any invalidation).
  void capture(RequestSnapshot snapshot) {
    _snapshot = snapshot;
    _invalidReason = null;
  }

  /// Drops the snapshot — the projection it described is gone.
  void invalidate(String reason) {
    _snapshot = null;
    _invalidReason = reason;
  }

  /// The snapshot when it is still valid for [model], else `null`.
  RequestSnapshot? validFor(Model model) {
    final snapshot = _snapshot;
    if (snapshot == null || snapshot.isValidFor(model)) return snapshot;
    return null;
  }
}

/// `selectCompactionMode` (GOAL #2394 D4 — AC1): the EXHAUSTIVE mode
/// table of a compaction run. No other mode exists and no outcome of a
/// run switches mode (I9 — no automatic fallbacks):
///
/// | setting      | S0 valid | separate digest role | mode        |
/// |--------------|----------|----------------------|-------------|
/// | `classic`    |    —     |          —           | `classic`   |
/// | `structured` |   yes    |         no           | `merged`    |
/// | `structured` |   any    |         yes          | `standalone`|
/// | `structured` |   no     |         no           | `standalone`|
///
/// `merged` is the hand-over call over the S0 prefix; `standalone` is the
/// today's digest under `affine` routing (a host that split the digest
/// onto a cheap smol role keeps it — not a fallback, the host's choice);
/// `classic` is the user's setting. Pure.
library;

import 'compaction.dart' show CompactionEngine;

/// How a compaction run talks to the model.
enum CompactionMode {
  /// `compaction.engine: classic` — the lossy prefix compactor, no tags,
  /// no merged call (byte-identical to the pre-#2394 classic path).
  classic,

  /// ONE hand-over call over the last main request (S0) + instruction.
  merged,

  /// The standalone digest (today's checkpoint call) — only when the host
  /// configured a separate digest/smol role or no valid S0 exists.
  standalone,
}

/// The mode table (D4). [snapshotValid] = a request snapshot exists and is
/// valid for the session's model; [separateDigestRole] = the host wired a
/// digest model that differs from the session's main model.
CompactionMode selectCompactionMode({
  required CompactionEngine engine,
  required bool snapshotValid,
  required bool separateDigestRole,
}) {
  if (engine == CompactionEngine.classic) return CompactionMode.classic;
  if (snapshotValid && !separateDigestRole) return CompactionMode.merged;
  return CompactionMode.standalone;
}

/// The post-run soft trigger of the merged hand-over (GOAL #2394 D8/D9 —
/// AC11/AC12): the soft pressure line, the hysteresis that keeps a run
/// from firing on every turn of the `[soft, hard)` band, and the
/// `compacting` gate that queues a prompt arriving while the post-run
/// call is in flight. Pure Dart — hosts own the counters.
///
/// - PRE-FLIGHT stays hard-only (`shouldCompact` — over the line → fold
///   before the request); the hard guard is never suppressed.
/// - POST-RUN fires the soft line: the bucket the main request just
///   warmed is still hot, so the merged call reads it from cache.
/// - Hysteresis: after any compaction run the soft trigger stays
///   suppressed until pressure reaches the hard line or N user turns
///   passed (`compaction.handOver.hysteresisTurns`, default 3).
/// - No cache-miss latch: a cold bucket never changes the mode — it is
///   a report signal only.
library;

import 'dart:async';
import 'dart:math' show max;

import 'compaction.dart' show CompactionSettings, shouldCompact;

/// Default `compaction.handOver.hysteresisTurns`.
const int handOverHysteresisTurnsDefault = 3;

/// The soft line's default distance below the hard line, as a share of
/// the window (`softRatio` unset): hard − 5 % of the window.
const double softRatioDefaultGap = 0.05;

/// The soft trigger line in tokens: `floor(softRatio × window)` when the
/// key is set, else the hard line minus [softRatioDefaultGap] of the
/// window (never below 1).
int softTriggerTokens({
  required int window,
  required CompactionSettings settings,
  double? softRatio,
}) {
  if (softRatio != null) return max(1, (window * softRatio).floor());
  final hard = window - settings.reserveTokens;
  return max(1, hard - (window * softRatioDefaultGap).floor());
}

/// Whether the POST-RUN soft trigger fires for [tokens]: at or over the
/// soft line, and either over the hard line (pressure the hysteresis
/// never suppresses) or past the hysteresis window.
bool softTriggerReached({
  required int tokens,
  required int window,
  required CompactionSettings settings,
  double? softRatio,
  required HandOverHysteresis hysteresis,
}) {
  if (!settings.enabled) return false;
  if (tokens >=
      softTriggerTokens(
        window: window,
        settings: settings,
        softRatio: softRatio,
      )) {
    return shouldCompact(tokens, window, settings) || hysteresis.allowSoft;
  }
  return false;
}

/// The soft-trigger hysteresis (D8): counts user turns, remembers the
/// turn of the last compaction run.
final class HandOverHysteresis {
  /// Creates a hysteresis with the configured turn window.
  HandOverHysteresis({this.turns = handOverHysteresisTurnsDefault});

  /// User turns that must pass after a run before the soft line may
  /// fire again (`compaction.handOver.hysteresisTurns`). Writable so a
  /// host that re-resolves its settings per run (the Flutter app) can
  /// keep ONE counter across config flips.
  int turns;

  int _turns = 0;
  int _turnsAtRun = -1 << 30;

  /// A user turn started (hosts call it at every prompt).
  void onTurn() => _turns++;

  /// A compaction run happened (success or failure alike — the band
  /// must not re-fire every turn over a failing endpoint).
  void recordRun() => _turnsAtRun = _turns;

  /// Turns passed since the last run (saturating).
  int get turnsSinceRun => max(0, _turns - _turnsAtRun);

  /// Whether the soft line may fire: no run yet, or the window passed.
  bool get allowSoft => turnsSinceRun >= turns;
}

/// The host-side holder of the two stateful pieces (CLI and Flutter
/// alike): the hysteresis and the `compacting` gate. Pure state — the
/// host owns WHEN to call [softReached] (post-run only, AC11) and
/// [recordRun] (after any compaction run, success or failure alike).
final class HandOverTriggerState {
  /// Creates the state; [turns] is `compaction.handOver.hysteresisTurns`
  /// (null → the default).
  HandOverTriggerState({int? turns})
    : hysteresis = HandOverHysteresis(
        turns: turns ?? handOverHysteresisTurnsDefault,
      );

  /// The soft-trigger hysteresis.
  final HandOverHysteresis hysteresis;

  /// The `compacting` gate — one run at a time, prompts wait.
  final CompactingGate gate = CompactingGate();

  /// Applies `compaction.handOver.hysteresisTurns` (null → the default)
  /// to the ONE counter — a host that re-resolves its settings per run
  /// calls this before every [softReached].
  void tune({int? hysteresisTurns}) =>
      hysteresis.turns = hysteresisTurns ?? handOverHysteresisTurnsDefault;

  /// A user turn started (hosts call it at every user prompt).
  void onTurn() => hysteresis.onTurn();

  /// A compaction run happened.
  void recordRun() => hysteresis.recordRun();

  /// Whether the POST-RUN soft line fires for [tokens].
  bool softReached({
    required int tokens,
    required int window,
    required CompactionSettings settings,
    double? softRatio,
  }) => softTriggerReached(
    tokens: tokens,
    window: window,
    settings: settings,
    softRatio: softRatio,
    hysteresis: hysteresis,
  );
}

/// The `compacting` flag (D9 — E33): ONE compaction at a time, and a
/// prompt arriving while the post-run call is in flight WAITS for it
/// ([wait]) instead of racing a second `_refreshState` or losing a
/// persist. Not a lock on the prompt — the prompt's own pre-flight then
/// measures the fresh basis.
final class CompactingGate {
  Completer<void>? _active;

  /// Whether a compaction run is in flight.
  bool get isCompacting => _active != null;

  /// Runs [body] as THE compaction; a nested/second run while one is in
  /// flight is joined to the first's completion instead of starting
  /// (never two writers).
  Future<T> run<T>(Future<T> Function() body) async {
    final active = _active;
    if (active != null) {
      await active.future;
      return body();
    }
    final completer = Completer<void>();
    _active = completer;
    try {
      return await body();
    } finally {
      _active = null;
      completer.complete();
    }
  }

  /// Resolves when no compaction is in flight (immediately when idle).
  Future<void> wait() async {
    while (true) {
      final active = _active;
      if (active == null) return;
      await active.future;
    }
  }
}

/// The stateful [Agent]: owns the transcript, queues steering/follow-up
/// messages, and exposes lifecycle hooks on top of the low-level loop.
///
/// Ported from pi-mono `packages/agent/src/agent.ts`. Deliberate divergences
/// from the TypeScript original:
///
/// - `AbortSignal` is [CancelToken]; `agent.abort()` cancels the run's token.
/// - `continue()` is [Agent.continueRun] (`continue` is a Dart keyword).
/// - pi's `prepareNextTurn` / `prepareNextTurnWithContext` pair collapses
///   into a single [PrepareNextTurnHook], which always receives the turn
///   context (the no-context variant is a closure that ignores it).
/// - pi's `convertToLlm` is absent: our messages are already LLM-shaped.
/// - pi defaults `streamFn` to `streamSimple` and tools self-execute; here
///   [Agent.streamFunction] is required and tool execution is injected —
///   either directly via [Agent.toolExecutor] or via a
///   [ToolRegistry] (`Agent(toolRegistry: ...)`), which also seeds the tool
///   list unless `tools` is passed explicitly.
/// - pi's `sessionId`, `thinkingLevel`/`thinkingBudgets`, `transport`,
///   `onPayload`/`onResponse`, `getApiKey`, and `maxRetryDelayMs` arrive with
///   the provider-options work they belong to.
library;

import 'dart:async';

import '../cancel_token.dart';
import '../context.dart';
import '../model.dart';
import '../skills/skills.dart' show Skill;
import '../types.dart';
import '../providers/payload_stall.dart'
    show lastOutboundEstimateBytes, payloadStallScaleFor;
import '../providers/provider_tuning.dart';
import 'agent_loop.dart';
import '../compaction/record_tag.dart' show TranscriptSeqMap;
import '../compaction/request_snapshot.dart' show RequestSnapshotStore;
import 'image_recovery.dart' show ImagePayloadRecoveryState;
import 'message_cap.dart' show MessageCapPolicy;
import 'misuse_breaker.dart';
import 'stuck_tool.dart';
import 'foreground_call_budget.dart';
import 'tool_registry.dart';

/// Thrown (as [ArgumentError]) when neither a tool executor nor a tool
/// registry is provided to [Agent.new].
Never _missingToolExecutor() {
  throw ArgumentError(
    'Agent requires either a toolExecutor or a toolRegistry.',
  );
}

/// Controls how many queued messages are injected when the loop reaches a
/// queue drain point. Ported from pi's `QueueMode`.
enum QueueMode {
  /// Drain and inject every queued message at that point.
  all,

  /// Drain and inject only the oldest queued message, leaving the rest for
  /// later drain points.
  oneAtATime,
}

/// Listener for agent lifecycle events (pi's `Agent.subscribe` callback).
///
/// Listeners are awaited in subscription order and are included in the
/// current run's settlement: the agent does not become idle until all
/// awaited listeners for `agent_end` have finished. [cancelToken] is the
/// active run's token.
typedef AgentListener =
    FutureOr<void> Function(AgentEvent event, CancelToken cancelToken);

/// Public agent state. Ported from pi's `AgentState`.
///
/// Assigning [tools] or [messages] copies the provided top-level list.
/// The runtime fields ([isStreaming], [streamingMessage],
/// [pendingToolCalls], [errorMessage]) are read-only for consumers; the
/// owning [Agent] mutates them as it processes loop events.
final class AgentState {
  AgentState({
    this.systemPrompt = '',
    required this.model,
    List<Tool> tools = const [],
    List<Message> messages = const [],
  }) : _tools = List.of(tools),
       _messages = List.of(messages);

  /// System prompt sent with each model request.
  String systemPrompt;

  /// Active model used for future turns.
  Model model;

  List<Tool> _tools;
  List<Message> _messages;

  /// Tools available to the model. Assigning copies the list.
  List<Tool> get tools => List.unmodifiable(_tools);
  set tools(List<Tool> value) => _tools = List.of(value);

  /// Conversation transcript. Assigning copies the list.
  List<Message> get messages => List.unmodifiable(_messages);
  set messages(List<Message> value) => _messages = List.of(value);

  /// True while the agent is processing a prompt or continuation.
  ///
  /// Remains true until awaited `agent_end` listeners settle.
  bool get isStreaming => _isStreaming;
  bool _isStreaming = false;

  /// Partial assistant message for the current streamed response, if any.
  Message? get streamingMessage => _streamingMessage;
  Message? _streamingMessage;

  /// Tool call ids currently executing.
  Set<String> get pendingToolCalls => Set.unmodifiable(_pendingToolCalls);
  final _pendingToolCalls = <String>{};

  /// Error message from the most recent failed or aborted assistant turn.
  String? get errorMessage => _errorMessage;
  String? _errorMessage;

  /// GOAL #2394: the tag epoch of the current transcript — the record
  /// alias every `state.messages` entry projects from (`null` = no tags:
  /// a classic-engine host, or a transcript not built from the session
  /// projection). Set by [refreshAgentState] / the host alongside
  /// `messages`; the loop stamps request COPIES from it, never the
  /// transcript.
  TranscriptSeqMap? recordSeqs;
}

/// Placeholder model mirroring pi's `DEFAULT_MODEL`, used when the caller
/// does not configure one.
const _defaultModel = Model(
  id: 'unknown',
  name: 'unknown',
  api: 'unknown',
  provider: 'unknown',
  baseUrl: '',
  contextWindow: 0,
  maxTokens: 0,
);

/// A FIFO of pending [Message]s with pi's drain semantics.
final class _PendingMessageQueue {
  _PendingMessageQueue(this.mode);

  /// How many messages [drain] returns.
  QueueMode mode;

  /// Fires synchronously on every [enqueue] — the agent loop's tool phase
  /// turns a mid-phase arrival into a soft-yield request.
  void Function()? onEnqueue;

  final _messages = <Message>[];

  void enqueue(Message message) {
    _messages.add(message);
    onEnqueue?.call();
  }

  bool hasItems() => _messages.isNotEmpty;

  /// How many messages are queued (issue #1786: the budget ladder's rung-1
  /// "steering FIFO non-empty" gate and its announcement counts).
  int get pendingCount => _messages.length;

  List<Message> drain() {
    if (mode == QueueMode.all) {
      final drained = List.of(_messages);
      _messages.clear();
      return drained;
    }
    if (_messages.isEmpty) return const [];
    return [_messages.removeAt(0)];
  }

  void clear() => _messages.clear();
}

final class _ActiveRun {
  _ActiveRun(this.source);

  final CancelTokenSource source;
  final completer = Completer<void>();
}

/// Stateful wrapper around the low-level agent loop.
///
/// Default for [Agent.runIdleTimeout]: eight minutes of event silence
/// outside tool execution. Legitimate silent windows are bounded well below
/// this — the connect timeout (180s) covers request setup and the provider
/// stream idle watchdog (300s) covers mid-stream gaps. The one declared
/// exception is the over-window relief compaction (issue #1085): it is
/// suspended around `overWindowRelief` instead of being allowed to fire
/// mid-relief and kill the run the relief is trying to save.
const defaultRunIdleTimeout = Duration(minutes: 8);

/// `Agent` owns the current transcript, emits lifecycle events, executes
/// tools, and exposes queueing APIs for steering and follow-up messages.
/// Port of pi's `Agent`.
class Agent {
  /// Creates an agent. See the library doc for the pi mapping.
  ///
  /// [toolExecutor] is optional when a [toolRegistry] is provided: the
  /// registry then supplies both the executor and (unless [tools] is given
  /// explicitly) the tool list. Passing both [toolExecutor] and
  /// [toolRegistry] is allowed; [toolExecutor] wins.
  Agent({
    Model? model,
    String? systemPrompt,
    List<Tool>? tools,
    List<Message>? messages,
    required this.streamFunction,
    ToolExecutor? toolExecutor,
    ToolRegistry? toolRegistry,
    this.beforeToolCall,
    this.afterToolCall,
    this.transformContext,
    this.budgetLineProvider,
    this.prepareNextTurn,
    this.externalSteeringSource,
    this.externalSteeringProbe,
    QueueMode steeringMode = QueueMode.oneAtATime,
    QueueMode followUpMode = QueueMode.oneAtATime,
    this.toolExecution = ToolExecutionMode.parallel,
    this.maxEmptyRetries = 1,
    this.emptyHiccupRetries = 3,
    this.emptyHiccupBaseDelay = const Duration(milliseconds: 500),
    this.emptyHiccupMaxBackoff = const Duration(milliseconds: 8000),
    this.runIdleTimeout = defaultRunIdleTimeout,
    this.onRunIdleTimeout,
    this.onRunWatchdogPaused,
    this.contextWindowCap,
    this.wireDump = false,
    this.overWindowRelief,
    this.messageCapPolicy,
    this.messageCapRelief,
    this.toolMisuseBreaker,
    this.stuckTool,
    this.foregroundCall,
    this.finalizeGate = false,
    this.operativeSkills = const [],
    Set<String>? reportedOrphanKeys,
  }) : toolExecutor =
           toolExecutor ?? toolRegistry?.executor ?? _missingToolExecutor(),
       _reportedOrphanKeys = reportedOrphanKeys ?? <String>{},
       _state = AgentState(
         model: model ?? _defaultModel,
         systemPrompt: systemPrompt ?? '',
         tools: tools ?? toolRegistry?.tools ?? const [],
         messages: messages ?? const [],
       ),
       _steeringQueue = _PendingMessageQueue(steeringMode),
       _followUpQueue = _PendingMessageQueue(followUpMode) {
    _steeringQueue.onEnqueue = () {
      if (!_steeringArrived.isClosed) _steeringArrived.add(null);
    };
  }

  final AgentState _state;
  final _listeners = <AgentListener>{};
  final _PendingMessageQueue _steeringQueue;
  final _PendingMessageQueue _followUpQueue;
  final _steeringArrived = StreamController<void>.broadcast(sync: true);
  _ActiveRun? _activeRun;
  Timer? _runWatchdogTimer;

  /// The window info the armed timer currently waits under — captured at
  /// arm time (gh-1617); the fire reports exactly what governed the wait.
  ({Duration window, String source, bool raised}) _armedRunIdleInfo = (
    window: defaultRunIdleTimeout,
    source: 'default',
    raised: false,
  );

  /// Backstop for wedged runs: when no [AgentEvent] arrives for this long
  /// outside tool execution (a stalled provider connection whose socket
  /// never errors, a hook future that never completes), the run's cancel
  /// token is cancelled with a [TimeoutException] reason and
  /// [onRunIdleTimeout] fires, so the turn ends as `aborted` instead of
  /// pinning the host's busy state forever. Streaming deltas and tool
  /// phases reset/disarm the timer — a long legitimate tool call (a full
  /// test gate) never trips it. [Duration.zero] disables the watchdog.
  /// Defaults to [defaultRunIdleTimeout].
  final Duration runIdleTimeout;

  /// Reports every run-idle watchdog fire (after [runIdleTimeout] of event
  /// silence); hosts log it for post-mortem "who held the busy row".
  final void Function(Object error)? onRunIdleTimeout;

  /// Reports every run-idle watchdog PAUSE (issue #1085 M3): the
  /// over-window relief is a declared long silent window, so [Agent]
  /// suspends the watchdog for its duration — hosts surface that pause
  /// visibly (a dim note), not only in the diagnostic log. Default: none.
  final void Function()? onRunWatchdogPaused;

  /// Opt-in raw wire dumps (issue #385 F5, default off): when on, every
  /// [ModelRequestEvent] carries the raw serialized outbound payload for
  /// the host to redact, cap, and persist. OFF by default — payloads can
  /// carry secrets and bloat the session file.
  final bool wireDump;

  /// The FinalizeGate (gh-1412, default off; attendance-corrected
  /// gh-1516): hosts set it on UNATTENDED runs (headless `fa -p`/bench —
  /// `AgentCliConfig.headlessRun`, never the approval mode). When on,
  /// every run parses the `task-ledger` block out of the final assistant
  /// answer (fenced or the unfenced near-miss shape), rewrites the
  /// answer so the transcript never shows the ledger, and emits
  /// [TaskLedgerEvent] for the host to persist as the hidden
  /// `task_ledger` session record. Runs with no tool calls (pure Q&A)
  /// fire nothing — no produced state, nothing to verify. Off =
  /// interactive behavior is byte-identical.
  ///
  /// Mutable: only the CLI host flips this today (boot `headlessRun`);
  /// the builder's `AgentWiringSpec` has no knob for it in v1 — hosts
  /// that want the gate must set the field after the stack lands.
  bool finalizeGate;

  /// gh-1409: the skills known to the session — their `operative:` lines
  /// ride every post-compaction request as the verbatim pinned carrier.
  /// Hosts republish on skill reload (the same way the system prompt's
  /// skills section recomposes). Empty (default) → byte-identical legacy
  /// requests. Mutable by design: `/skills reload` and availability
  /// toggles swap the list.
  List<Skill> operativeSkills;

  /// gh-1449: the session's one-shot latch of already-reported orphan
  /// results ([orphanReportKey]s, mutable — the agent loop adds every key
  /// it reports back into this same set, at DELIVERY: the request carrying
  /// the note must have streamed (gh-2270)). Hosts seed it from the
  /// persisted `orphan_report` custom records when a session resumes
  /// ([orphanReportKeysFromRecords]), so a restored session never
  /// re-reports an orphan it already reported (AC6).
  Set<String> get reportedOrphanKeys => _reportedOrphanKeys;
  final Set<String> _reportedOrphanKeys;

  /// GOAL #2394 (AC2): the session's request snapshots (S0) — the last
  /// main send as sent, overwritten at every send seam and read by the
  /// compaction host for the cache-affine hand-over call. Hosts
  /// invalidate it on branch switch / checkpoint restore and after a
  /// successful compaction run.
  final RequestSnapshotStore requestSnapshots = RequestSnapshotStore();

  /// GOAL #2394 (AC8, E37): whether main requests carry the `m<seq>`
  /// record tags — only under the structured compaction engine. OFF by
  /// default: a host opts in when it resolves the structured engine (the
  /// CLI and the Flutter app sync it from their engine setting); a
  /// classic-engine host keeps the pre-#2394 wire byte-identically — no
  /// tags, no merged hand-over, one cache invalidation at the switch.
  bool recordTagsEnabled = false;

  /// Drops the current request snapshot — hosts call it when the
  /// projection it described is gone (branch switch, checkpoint restore,
  /// a successful compaction run).
  void invalidateRequestSnapshot(String reason) =>
      requestSnapshots.invalidate(reason);

  /// Issue #1750: run-lifetime learned image caps, keyed by
  /// [imageCapLatchKey] — the loop latches a provider-refused cap here;
  /// runtime-only, never persisted.
  final Map<String, int> _imageCapLatches = {};

  /// gh-1934: the session-scoped 413 image-payload recovery state — the
  /// loop's ladder halves the adaptive budget and latches the strip-all
  /// here on a payload-size refusal, keyed per (provider, model) like
  /// [_imageCapLatches] (issue #2269 — a `/model` switch starts the new
  /// pair clean); every later request build of the latched pair rides the
  /// recovered state (runtime-only, never persisted).
  final ImagePayloadRecoveryState imageRecovery = ImagePayloadRecoveryState();

  /// Provider adapter used for every model call. See [StreamFunction].
  StreamFunction streamFunction;

  /// Executes tool calls requested by the model. See [ToolExecutor].
  ToolExecutor toolExecutor;

  /// The tool-misuse circuit breaker (issue #862): 3 consecutive identical
  /// tool-call rejections arm a corrective note in the next request
  /// payload; 6 stop executing that identical call for the rest of the run.
  /// `null` (default) disables it — byte-identical to the pre-breaker
  /// harness.
  ToolMisuseBreaker? toolMisuseBreaker;

  /// Called before a tool is executed; can block it. See [BeforeToolCallHook].
  BeforeToolCallHook? beforeToolCall;

  /// Called after a tool finishes; can override the result.
  /// See [AfterToolCallHook].
  AfterToolCallHook? afterToolCall;

  /// Rewrites the message list sent to the provider before each call.
  /// See [TransformContextHook].
  TransformContextHook? transformContext;

  /// gh-1556: the session deadline's per-turn budget line provider
  /// (`time-left: 5min`), threaded into every [AgentLoopConfig] the agent
  /// builds. Consulted live before each provider call; null/absent keeps
  /// the request payload byte-for-byte. Mutable like [transformContext]:
  /// hosts attach it after construction.
  String? Function()? budgetLineProvider;

  /// Adjusts context/model between turns. See [PrepareNextTurnHook].
  PrepareNextTurnHook? prepareNextTurn;

  /// Owner-side effective context override (`agent.contextWindowCap`,
  /// issues #273/#729), threaded into every [AgentLoopConfig] the agent
  /// builds so the loop's over-window guard trips at the overridden
  /// window — clamped down under the catalog value, raised above it when
  /// the endpoint serves more than the catalog reports. `null` = the raw
  /// model window.
  final int? contextWindowCap;

  /// Emergency relief for the loop's over-window guard (issue #387),
  /// threaded into every [AgentLoopConfig]. `null` = the guard keeps
  /// today's behavior (verbatim error, no mid-turn compaction). Mutable
  /// like the other late-wirable host knobs ([streamFunction],
  /// [externalSteeringSource]): hosts that build the agent before the
  /// service exists (the app's pre-constructed-agent constructor) attach
  /// the relief right after (gh-1077).
  OverWindowRelief? overWindowRelief;

  /// gh-1680: the learned per-model message-cap policy threaded into every
  /// [AgentLoopConfig]. `null` = the loop keeps the pre-gh-1680 behavior
  /// (a cap-400 refusal is terminal). Mutable like [overWindowRelief].
  MessageCapPolicy? messageCapPolicy;

  /// gh-1680: the host compaction pass for the message-cap self-heal
  /// (see [MessageCapRelief]), threaded into every [AgentLoopConfig].
  /// Only fires when [messageCapPolicy] classified the refusal.
  MessageCapRelief? messageCapRelief;

  /// Observer for output-truncated tool calls (issue #1829, Core flow B),
  /// threaded into every [AgentLoopConfig]. The task executor wires the
  /// deliverable capture here so a truncated `reply`/`agent_message` body
  /// survives as a partial artifact; the calls themselves stay failed
  /// unexecuted. Mutable like the other late-wirable knobs. The loop
  /// awaits the observer (gh-1956 review): the capture's salvage persist
  /// must finish its restore-before-id-allocation dance before the
  /// failure result is emitted.
  Future<void> Function(ToolCall call)? onTruncatedToolCall;

  /// Stuck-call supervision (gh-1054), threaded into every
  /// [AgentLoopConfig]: liveness heartbeats for long-running tool calls
  /// plus the autonomous cancel/retry/convert follow-up. `null` =
  /// unsupervised.
  final StuckToolConfig? stuckTool;

  /// Foreground tool-call budget (issue #1786), threaded into every
  /// [AgentLoopConfig]: bounds how long a running foreground tool call can
  /// keep the agent unreachable by steering. `null` = the 10-minute
  /// default applies.
  final ForegroundCallBudgetConfig? foregroundCall;

  /// Late-wirable host controls for the budget ladder's one-key offer and
  /// the watchdog escalate hook (issue #1786) — set by the interactive host
  /// after construction, same pattern as [externalSteeringSource]. `null` =
  /// headless/unattended: rung 1 waits for rung 2 (or auto-converts).
  ForegroundCallBudgetControls? foregroundBudgetControls;

  /// External messages merged into the steering poll at every turn boundary
  /// (before the first turn and after each one) — e.g. the agent's inbox in
  /// the messaging fabric. Drained BEFORE the in-process steering queue.
  /// Contract: must not throw; return an empty list when nothing arrived.
  QueuedMessagesSource? externalSteeringSource;

  /// Non-draining probe paired with [externalSteeringSource]: returns true
  /// when the external source has messages pending. Polled on a slow timer
  /// during tool-call phases so external mail also triggers the soft-yield
  /// of long-running tools (steering delivery itself stays at the boundary).
  Future<bool> Function()? externalSteeringProbe;

  /// Fires whenever a message is enqueued into the steering queue mid-run;
  /// the agent loop subscribes per tool-call phase to request soft-yields.
  Stream<void> get steeringArrived => _steeringArrived.stream;

  /// Tool execution strategy for assistant messages that contain multiple
  /// tool calls.
  ToolExecutionMode toolExecution;

  /// How many times a degenerate-empty assistant response is retried within
  /// the loop before the turn is accepted. Default: 1.
  final int maxEmptyRetries;

  /// gh-1577: how many times an empty completion that follows PARTIAL
  /// content is retried with exponential backoff before the run ends with
  /// the explicit empty-exhaustion error. See
  /// [AgentLoopConfig.emptyHiccupRetries]. Default: 3.
  final int emptyHiccupRetries;

  /// gh-1577: first backoff sleep between empty-hiccup retries. See
  /// [AgentLoopConfig.emptyHiccupBaseDelay]. Default: 500ms.
  final Duration emptyHiccupBaseDelay;

  /// gh-1577: cap on the exponential empty-hiccup backoff. See
  /// [AgentLoopConfig.emptyHiccupMaxBackoff]. Default: 8s.
  final Duration emptyHiccupMaxBackoff;

  /// Current agent state.
  AgentState get state => _state;

  /// Controls how queued steering messages are drained.
  QueueMode get steeringMode => _steeringQueue.mode;
  set steeringMode(QueueMode mode) => _steeringQueue.mode = mode;

  /// Controls how queued follow-up messages are drained.
  QueueMode get followUpMode => _followUpQueue.mode;
  set followUpMode(QueueMode mode) => _followUpQueue.mode = mode;

  /// Subscribe to agent lifecycle events. Returns an unsubscribe function.
  ///
  /// Listener futures are awaited in subscription order and included in the
  /// current run's settlement. `agent_end` is the final loop event for a
  /// run; `agent_settled` follows once the run and all queued follow-ups are
  /// fully idle, and the agent does not become idle until all awaited
  /// listeners for those events have settled (pi semantics).
  void Function() subscribe(AgentListener listener) {
    _listeners.add(listener);
    return () => _listeners.remove(listener);
  }

  /// Queue a message to be injected after the current assistant turn
  /// finishes.
  void steer(Message message) => _steeringQueue.enqueue(message);

  /// Queue a message to run only after the agent would otherwise stop.
  void followUp(Message message) => _followUpQueue.enqueue(message);

  /// Fires the steering-arrived notification WITHOUT queueing a message —
  /// the external-inbox fast path (issue #647): the owner of the external
  /// source (e.g. the task executor seeing mail land on a running child's
  /// handle) pokes the run so the tool-call phase's soft-yield fires
  /// instantly instead of waiting out the 2s external probe. Delivery
  /// itself still happens once, at the boundary drain.
  void pokeSteering() {
    if (!_steeringArrived.isClosed) _steeringArrived.add(null);
  }

  /// Host-visible notices for the provider-phase steering interrupt
  /// (issue #1923 AC4). Null keeps the core silent; interactive hosts
  /// print the lines verbatim (the copy is pinned by the issue).
  void Function(String line)? onSteeringInterruptNotice;

  /// The mid-stream steering stall window PROVIDER (issue #1923 AC1):
  /// re-EVALUATED at every steering signal and stall re-arm — never a
  /// per-run snapshot (bot r2, thread `PRRT_kwDOTXdlLc6wfxlV`: the
  /// watchdog re-windows on every arm, so the steering interrupt must
  /// chase the window that is actually armed or a mid-run failover to a
  /// shorter entry lets the whole-run kill win the race AC1 says steering
  /// always wins). Prefers [_armedRunIdleInfo] — the window the watchdog
  /// timer is ACTUALLY armed with — over a fresh derivation, and keeps
  /// the 30s margin (payload scaling included, since the armed window was
  /// resolved through [runIdleWindow]). `Duration.zero` when the watchdog
  /// is disabled: the mid-stream interrupt stays off, the zero-byte
  /// immediate interrupt is unaffected.
  Duration get _steeringStallWindowNow {
    if (runIdleTimeout == Duration.zero) return Duration.zero;
    final armed = _armedRunIdleInfo.window;
    final base = armed > Duration.zero ? armed : runIdleWindow.window;
    final window = base - const Duration(seconds: 30);
    return window <= Duration.zero ? Duration.zero : window;
  }

  /// Remove all queued steering messages.
  void clearSteeringQueue() => _steeringQueue.clear();

  /// Drain the steering queue and return its messages (abort path: the
  /// queued steers must land in the transcript, not vanish).
  List<Message> drainSteeringQueue() => _steeringQueue.drain();

