/// the coalesce target to arm for the retried request (null = cap unknown,
/// nothing to coalesce toward), and the terminal turn for the abort case.
typedef _MessageCapHealStep = ({
  Context? context,
  int? coalesceTarget,
  (AssistantMessage, Context)? terminal,
