      default:
        if (partialMessage != null) {
          partialMessage = _stampAgainstUsed(event.partial, used);
          context.messages[context.messages.length - 1] = partialMessage;
          await emit(
            MessageUpdateEvent(
              message: partialMessage,
              assistantMessageEvent: event,
