}

/// Issue #387: emergency relief for the loop's over-window guard — an
/// extension so agent_cli.dart stays under the 2800-line size gate.
extension OverWindowGuardRelief on AgentCli {
  /// ONE synchronous compaction pass over the live transcript, run when
  /// the loop's guard is about to refuse an over-window request. Returns
  /// the relieved message list to retry with, or `null` when nothing
  /// hideable remains (or the pass failed to shrink anything) — the loop
  /// then surfaces its verbatim guard error. The loop re-measures the
  /// returned list on the same basis ([_liveRequestTokens]), so a list
  /// that is still over the window is refused there too (E1 fail-fast,
  /// never a loop).
  Future<List<Message>?> _relieveOverWindow(List<Message> overWindow) async {
    if (_session == null) return null;
    _logDiagnostic(
      'over-window relief start sid=$_logSid '
      'messages=${_agent.state.messages.length}',
    );
    final beforeTokens = estimateRequestTokens(
      overWindow,
      systemPrompt: _agent.state.systemPrompt,
      tools: _agent.state.tools,
    );
    // gh-209: the relief path runs ONLY the emergency tier —
    // deterministic, seconds, no LM call on any path. The quality tier
    // (judge/checkpoints) owns the turn boundaries (the post-run fold
    // and the pre-flight); a slow or unusable judge class can no longer
    // turn an in-turn overflow into a ≤15 min silent stall.
    _pushBusyPhase('Compacting context…');
    final EmergencyReliefOutcome reliefOutcome;
    try {
      reliefOutcome = await _runEmergencyRelief();
    } finally {
      _pushBusyPhase('');
    }
    final after = _agent.state.messages.toList();
    final afterTokens = _liveRequestTokens();
    if (afterTokens >= beforeTokens) {
      _logDiagnostic('over-window relief no-op sid=$_logSid');
      return null;
    }
    _logDiagnostic(
      'over-window relief done sid=$_logSid tokens=$afterTokens '
      '(was $beforeTokens, ${after.length} messages, '
      'hidden=${reliefOutcome.hiddenRecords}, '
      'trim=${reliefOutcome.usedTrimValve})',
    );
    // Issue #1085 M3: the relieved turn CONTINUES — say so visibly, the
    // post-compaction silence is exactly what this run must never do. A
    // reduce-but-still-over relief stays unmarked: the guard's verbatim
    // error is the honest next line there (the loop re-measures the
    // returned list on the window basis).
    if (afterTokens <= _effectiveContextWindow) {
      io.writeln(
        _style.dim('[resuming] continuing the turn on the compacted context'),
      );
    }
    return after;
  }

  /// The emergency tier over the live session (gh-209): deterministic
  /// hide (dedup reads, keep-N-recent per tool class) + the local trim
  /// valve. No LM call is attempted on ANY path. Every CLI compaction
  /// entry point awaits inline (there is no fire-and-forget compactor),
  /// so this cannot overlap the quality tier's post-run pass.
  Future<EmergencyReliefOutcome> _runEmergencyRelief() async {
    final relief = EmergencyRelief(
      session: _session!,
      state: _agent.state,
      window: _effectiveContextWindow,
      settings: _effectiveCompactionSettings,
    );
    final outcome = await relief.run();
    // The relief re-anchored the live transcript from the session
    // projection (refreshAgentState) — keep the persist cursor in step,
    // exactly like the quality tier's post-run bookkeeping.
    _persistedCount = _agent.state.messages.length;
    return outcome;
  }
}

/// gh-1680: the message-cap self-heal's host relief. The provider refused
/// the request because the message ARRAY exceeded its cap (not the
/// tokens), so the success criterion here is the MESSAGE COUNT, not the
/// token estimate ([_relieveOverWindow]'s no-op test would misjudge a
/// token-healthy transcript). ONE synchronous compaction pass over the
/// live transcript; returns the relieved list for the loop's single
/// retry, or null when the count could not be reduced (nothing hideable —
/// the retry then rides the coalesced payload alone, and a second refusal
/// surfaces the terminal error).
extension AgentCliMessageCapRelief on AgentCli {
  Future<List<Message>?> _relieveMessageCap(List<Message> overCap) async {
    if (_session == null) return null;
    _logDiagnostic(
      'message-cap relief start sid=$_logSid messages=${overCap.length}',
    );
    final beforeCount = overCap.length;
    // gh-209: the emergency tier ONLY — the trim valve owns the
    // message-count dimension (the hide passes fold groups into
    // markers, which keeps the count; the valve bounds it mechanically).
    _pushBusyPhase('Compacting context…');
    final EmergencyReliefOutcome reliefOutcome;
    try {
      reliefOutcome = await _runEmergencyRelief();
    } finally {
      _pushBusyPhase('');
    }
    final after = _agent.state.messages.toList();
    if (after.length >= beforeCount) {
      _logDiagnostic('message-cap relief no-op sid=$_logSid');
      return null;
    }
    _logDiagnostic(
      'message-cap relief done sid=$_logSid messages=${after.length} '
      '(was $beforeCount, hidden=${reliefOutcome.hiddenRecords}, '
      'trim=${reliefOutcome.usedTrimValve})',
    );
    io.writeln(
      _style.dim(
        '[message cap] context compacted before the retry — continuing '
        'the turn',
      ),
    );
    return after;
  }
}

/// Over-window continuation funnel (issue #1085 M2; moved from
/// agent_cli.dart under the repo's 2800-line size gate). Same library, so
/// private state is in scope.
///
/// The bounded-retry budget: the old single shot died quietly whenever one
/// compaction pass freed less than the whole window.
const int _overWindowContinueAttempts = 2;

/// Delivered to the model when the over-window guard stopped a run and
/// the post-run compaction freed the window: names what happened and
/// how to avoid re-filling the context.
const String _overWindowContinuationNotice =
    '<system-notice>\n'
    'The previous run was stopped by the context-window guard: the '
    'outgoing request exceeded the model window and was NOT sent. The '
    'transcript was auto-compacted just now (most of it is preserved as '
    'a summary; the session file keeps the full history). Continue the '
    'interrupted task from where it stopped. Avoid re-reading whatever '
    'filled the window (huge tool outputs, whole files) — use targeted '
    'reads (offset/limit or :A-B selectors) instead.\n'
    '</system-notice>';

/// One post-compaction relief verdict (issue #2264): a PURE decision
/// over the POST-RUN measurements, table-pinned in
/// test/cli/agent_cli_over_window_continuation_retry_test.dart. The
/// stale PRE-RUN overCap gate does NOT participate — issue #2264
/// removed it from the criterion (a pass that relieved BOTH dimensions
