  void _startSessionWatch() {
    _stopSessionWatch();
    if (!_watchExternalSessions) return;
    final file = _sessionFile;
    if (file == null) return;
    _sessionWatchBytes = -1;
    _sessionWatchTimer = Timer.periodic(const Duration(seconds: 2), (_) {
      unawaited(_checkSessionFileGrew());
    });
