  Future<void> _afterRun() async {
    // A TTSR abort/inject/retry chain may still be in flight when the
    // aborted run settles; persist only once the whole chain completed.
    await _ttsr?.settled;
    _hubCompletePanels();
    await _persistMessages();
    // gh-1590: a run finalize gives the job board a chance to land its
    // snapshot — UNFORCED, inside the persist window: the drain path
    // completes one run per settle notice, and a force here would append
    // one record per reaction run, defeating the coalescing. The final
    // state rides the trailing leg or the shutdown flush instead; when
    // the window is open the gate skips the encode entirely.
    await _persistJobBoard();
    try {
      // GOAL #2394 (D9): the post-run call runs under the `compacting`
      // gate — a prompt arriving meanwhile waits for it.
      await _handOverTrigger.gate.run(() => _maybeAutoCompact(postRun: true));
    } on CancelledException {
      // Abort during the POST-RUN compaction window (issue #1085 round-4
      // review): the turn has already settled and reported its outcome —
      // rethrowing here would re-enter error handling and print a
      // spurious `error: CancelledException` line over a finished turn.
      // The dim note is the receipt; the next prompt starts clean.
      _renderUserCancel('compaction interrupted');
    }
  }

  /// gh-1556: the armed deadline rides along as `FA_DEADLINE_EPOCH_MS`, so
  /// a mid-session `/timer` adjustment is picked up by the next command —
  /// the chip, the request line and the shell all see the ONE clock.
  /// Unarmed, the key still rides as an EMPTY scrub sentinel: `LocalShell`
  /// merges the overlay OVER `Platform.environment`, so omitting the key
  /// would leave a stale host-exported `FA_DEADLINE_EPOCH_MS` visible to
  /// bash children after `/timer clear` — and `resolveSessionDeadline`
  /// treats an empty value as feature-off, exactly like no export.
  /// (Relocated from agent_cli.dart for the 2800-line loc gate.)
  Future<Map<String, String>> _sessionEnvVars() async {
    final session = _session;
    final metadata = session == null ? null : await session.getMetadata();
    return {
      if (metadata != null) sessionIdEnvVar: metadata.id,
      if (metadata != null) sessionFileEnvVar: metadata.path,
      providerEnvVar: _providerKind,
      modelEnvVar: _agent.state.model.id,
      if (_deadline.isArmed)
        deadlineEpochMsEnvVar: '${_deadline.deadlineEpochMs}'
      else
        deadlineEpochMsEnvVar: '',
      ..._runtimeSecrets,
    };
  }
}

