  Future<bool> _maybeAutoCompact({
    bool forceE1Pass = false,
    bool postRun = false,
  }) async {
    final session = _session;
    if (session == null) return false;
    if (_agent.state.messages.isEmpty) return false;
    // An aborted turn gets no fresh compaction pass (issue #1085 round-2
    // review): the sticky abort flag used to belt-throw CancelledException
    // out of the post-run compaction and print a spurious `error:` line
    // after the abort was already reported. The over-window guard simply
    // re-fires on the next turn if the transcript is still too big.
    if (_runAbortRequested) return false;
    // The same request-size basis as the loop's over-window guard and the
    // status-line meter (transcript + system-prompt/tool-schema overhead
    // when unanchored) — the threshold must trip on what the next request
    // actually carries.
    final tokens = _liveRequestTokens();
    // gh-1680 AC4: the additive message-count trigger — a model with a
    // learned cap compacts when the live count reaches `cap − margin`,
    // BEFORE the request, even when the token trigger is untouched. The
    // gate also consumes the one-shot E1 pass a cap-unknown refusal
    // armed (PR #1695).
    final model = _agent.state.model;
    final e1PassPending =
        forceE1Pass &&
        _modelCaps.isPremptivePassPending(model.provider, model.id);
    // gh-2259: the CONSUMING gate is legal only where the armed pass
    // will actually EXECUTE — a forced run (the pre-flight,
    // `forceE1Pass`). The post-run and over-window folds run unforced:
    // the gate's one-shot take consumed an armed pass there, the
    // unforced run executed zero passes (the engine short-circuits under
    // the token trigger), and the next request re-learned the refusal
    // the hard way. Unforced folds consult the LEARNED-CAP dimension
    // only — the armed pass stays armed for the next pre-flight, which
    // consumes it with `force: true` (the gh-1729 peek discipline).
    final overCap = e1PassPending
        ? _messageCapGateReached()
        : messageCapTriggerReached(
            _agent.state.messages.length,
            _modelCaps.learnedCapFor(model),
          );
    final hard =
        shouldCompact(
          tokens,
          _effectiveContextWindow,
          _effectiveCompactionSettings,
        ) ||
        overCap;
    // GOAL #2394 (AC11/D8): the POST-RUN soft line arms the merged
    // hand-over alone — in the [soft, hard) band, muted by the hysteresis
    // for N user turns after any run. The pre-flight and the over-window
    // guard stay hard-only: the hard guard is never suppressed.
    _handOverTrigger.tune(
      hysteresisTurns: config.compactionTuning?.handOverHysteresisTurns,
    );
    final soft =
        !hard &&
        postRun &&
        _handOverTrigger.softReached(
          tokens: tokens,
          window: _effectiveContextWindow,
          settings: _effectiveCompactionSettings,
          softRatio: config.compactionTuning?.softRatio,
