    this.toolExecution = ToolExecutionMode.parallel,
    this.beforeToolCall,
    this.afterToolCall,
    this.transformContext,
    this.prepareNextTurn,
    this.overWindowRelief,
    this.messageCapPolicy,
    this.messageCapRelief,
    this.getSteeringMessages,
    this.getFollowUpMessages,
    this.steeringNotifications,
    this.hasPendingSteering,
    this.maxEmptyRetries = 1,
    this.emptyHiccupRetries = 3,
    this.emptyHiccupBaseDelay = const Duration(milliseconds: 500),
    this.emptyHiccupMaxBackoff = const Duration(milliseconds: 8000),
    this.maxSteeringTurns = 20,
    this.contextWindowCap,
    this.wireDump = false,
    this.toolMisuseBreaker,
    this.stuckTool,
    this.foregroundCallBudget,
    this.pendingSteeringCount,
    this.foregroundBudgetControls,
    this.finalizeGate = false,
    this.operativeSkills = const [],
    this.reportedOrphanKeys,
    this.budgetLineProvider,
    this.imageCapLatches,
    this.imageRecovery,
    this.onTruncatedToolCall,
    this.steeringStallWindow = _defaultSteeringStallWindow,
    this.steeringInterruptNotice,
    this.recordSeqs,
    this.requestSnapshots,
  });

  /// The model to call each turn.
  final Model model;

  /// How tool calls within one assistant message are executed.
  /// Default: [ToolExecutionMode.parallel] (pi default).
  final ToolExecutionMode toolExecution;

  /// Called before each tool execution; can block it.
  final BeforeToolCallHook? beforeToolCall;

  /// Called after each tool execution; can override the result.
  final AfterToolCallHook? afterToolCall;

  /// Rewrites the message list sent to the provider before each call.
  final TransformContextHook? transformContext;

  /// Adjusts context/model between turns.
  final PrepareNextTurnHook? prepareNextTurn;

  /// Emergency relief for the over-window guard (issue #387). Called at
  /// most once per response before the guard's refusal surfaces; see
  /// [OverWindowRelief]. `null` = the guard keeps today's behavior.
  final OverWindowRelief? overWindowRelief;

  /// gh-1680: the learned per-model message-cap policy: a classified cap
  /// refusal is learned and the loop retries ONCE (coalesced payload +
  /// [messageCapRelief] compaction). `null` = pre-gh-1680 behavior.
  final MessageCapPolicy? messageCapPolicy;

  /// gh-1680: the host compaction pass for the message-cap self-heal; see
  /// [MessageCapRelief]. Fires only when [messageCapPolicy] classified.
  final MessageCapRelief? messageCapRelief;

  /// Steering messages to inject at the next turn boundary.
  final QueuedMessagesSource? getSteeringMessages;

  /// Follow-up messages to process after the run would otherwise stop.
  final QueuedMessagesSource? getFollowUpMessages;

  /// Fires when a steering message arrives mid-run (the in-process queue).
  /// The tool-call phase turns the first arrival into a soft-yield request
  /// (see [currentYieldToken]): yield-aware long-running tools (bash, task)
  /// finish the tool call early WITHOUT stopping the underlying work, so the
  /// user message is delivered at the next step boundary instead of waiting
  /// for the whole tool call.
  final Stream<void>? steeringNotifications;

  /// Probes for externally pending steering (e.g. the messaging inbox)
  /// WITHOUT draining it — polled on a slow timer during the tool-call
  /// phase as a second yield trigger. Null when the host has no external
  /// steering source.
  final Future<bool> Function()? hasPendingSteering;

  /// The mid-stream steering stall window PROVIDER (issue #1923 AC1):
  /// evaluated at every steering signal and stall re-arm — never
  /// snapshotted per run (bot r2, thread `PRRT_kwDOTXdlLc6wfxlV`: the
  /// watchdog re-windows on EVERY arm, so a mid-run failover must be able
  /// to shrink the steering window with it). Returns how long an
  /// in-flight provider stream may stay silent after a steering arrival
  /// before the attempt counts UNPRODUCTIVE and is interrupted (zero-byte
  /// attempts interrupt immediately regardless). `<= 0` disables the
  /// mid-stream interrupt. Hosts derive it BELOW the actually-armed
  /// run-idle watchdog window so the interrupt wins the race against the
  /// whole-run kill (the [Agent] uses `armed window - 30s`, payload
  /// scaling inherited).
  final Duration Function() steeringStallWindow;

  /// Host-visible notices for the provider-phase steering interrupt
  /// (issue #1923 AC4) — the pinned queued/delivered lines. Null keeps
  /// the core silent.
  final void Function(String line)? steeringInterruptNotice;

  /// GOAL #2394: the transcript's tag epoch — every request copy is
  /// stamped `m<seq>` from it before the request transforms (null = no
  /// tags; the transcript itself is never modified).
  final TranscriptSeqMap? recordSeqs;

  /// GOAL #2394: the main-send seam writes the request snapshot (S0)
  /// here on every send; null disables capturing.
  final RequestSnapshotStore? requestSnapshots;

  /// How many times a degenerate EMPTY completion (stopReason `stop`, no
  /// tool calls, no text — some providers answer like this under load) is
  /// retried with the same context before the turn accepts it. Default: 1
  /// (one automatic retry — a blank answer never ends a run on the first
  /// try).
  final int maxEmptyRetries;

  /// gh-1577: how many times an empty completion that follows PARTIAL
  /// content (assistant text, tool activity, or a truncation signal — see
  /// [classifyEmptyCompletion]'s `emptyAfterPartial` verdict) is retried
  /// with exponential backoff before the run ends with an explicit
  /// empty-exhaustion error instead of settling a silent success. Default:
  /// 3. `0` still converts an empty-after-partial into the exhaustion error
  /// after the [maxEmptyRetries] budget — the never-settle-empty contract
  /// is not switchable off.
  final int emptyHiccupRetries;

  /// gh-1577: first backoff sleep between empty-hiccup retries (the
  /// model-roles `retry.baseDelayMs` shape).
  final Duration emptyHiccupBaseDelay;

  /// gh-1577: cap on the exponential empty-hiccup backoff (the model-roles
  /// `retry.maxBackoffMs` shape).
  final Duration emptyHiccupMaxBackoff;

  /// How many steering batches may extend ONE run (mid-run user input or
  /// external mail). Without a cap, a self-sustaining agent chatter loop
  /// (every inbound message steers a reply that triggers the next
  /// inbound) extends the run forever — the spinner never stops and
  /// typed input queues behind an endless turn. Once the cap is reached
  /// the run settles; undelivered steering stays queued and is picked up
  /// by the next run (whose own wake caps apply). Default: 20.
  final int maxSteeringTurns;

  /// Owner-side effective context override (`agent.contextWindowCap`,
  /// issues #273/#729). The over-window guard measures the outgoing
  /// request against [effectiveContextWindow] — a 1M-window model run
  /// under a 256k owner cap trips the guard at 256k, not 1M, and a
  /// 200k-catalog model whose endpoint serves ~1M runs at the raised cap
  /// instead of falsely overflowing at the catalog value. `null` =
  /// uncapped: the raw model window, byte-identical to the pre-cap loop.
  final int? contextWindowCap;

  /// Opt-in raw wire-dump capture (issue #385 F5). When true, every
  /// [ModelRequestEvent] carries `rawWireDump` — the serialized outbound
  /// request JSON BEFORE provider shaping; hosts redact through their
  /// active pipeline and cap before persisting. Default: false.
  final bool wireDump;

  /// Observer for every tool call failed by output truncation (issue
  /// #1829, Core flow B): fired with the salvage-parsed call so a
  /// harness-owned capture can persist deliverable TEXT (reply /
  /// agent_message bodies) as a partial artifact. Capture-only — the
  /// call is still failed unexecuted, never executed; awaited before
  /// the failure result (gh-1956): persist re-seeds durable ids first.
  final Future<void> Function(ToolCall call)? onTruncatedToolCall;

  /// The tool-misuse circuit breaker (issue #862): N consecutive identical
  /// rejections of the same tool arm a corrective note for the next request
  /// payload; M stop executing that identical call for the rest of the run.
  /// `null` disables the breaker entirely — behavior is byte-identical to
