/// boundaries). Stops BEFORE the request instead of silently sending a
/// context the model cannot fit — the run ends with a clear error, the
/// tool results stay in the session, and the post-run auto-compaction
/// (with its local-trim valve) shrinks the transcript for the next turn.
/// Only a GROSS overflow trips this (past the window itself): between the
/// compaction trigger (window - reserve) and the window, the normal
/// post-run compaction flow still owns the decision.
///
/// Issue #387 emergency relief: offers the host ONE synchronous
/// compaction over the live transcript before giving up. A non-null
/// result replaces the loop context (`retried`) and the request is
/// rebuilt and retried; null, a throw, or a still-over result keeps the
/// verbatim guard error. Bounded to one attempt — a tool result bigger
/// than the window fails fast here instead of looping.
typedef _OverWindowGuardStep = ({
  /// The loop's live context after the guard (relief may have replaced
  /// it — adopt when [retried]).
  Context context,
  bool reliefUsed,
  bool retried,
  (AssistantMessage, Context)? terminal,
});

Future<_OverWindowGuardStep> _overWindowGuardTurn(
  Context context,
  Context requestContext,
  AgentLoopConfig config,
  AgentEventSink emit,
  bool reliefUsed,
  CancelToken? cancelToken,
  int window,
  int tokens,
) async {
  // `window`/`tokens` are computed synchronously by the caller (the same
  // accounting basis as the host's ctx meter and the compaction
  // threshold: transcript estimate PLUS the system-prompt / tool-schema
  // overhead when no provider-usage anchor prices them in — an
  // unanchored estimate otherwise undercounts every request by that
  // overhead — the "meter said 64% but the request was over-window"
  // mismatch).
  if (window <= 0 || tokens <= window) {
    return (
      context: context,
      reliefUsed: reliefUsed,
      retried: false,
      terminal: null,
    );
  }
  if (_reliefAvailable(reliefUsed, config)) {
    try {
      final relieved = await config.overWindowRelief!(context.messages);
      if (_isCancelRequested(cancelToken)) {
        // Issue #1085: the relief tokens are linked to the run token —
        // a USER abort mid-relief cancels the compaction and lands
        // here. The run must end aborted, NOT with the guard error:
        // the guard error re-arms the host's auto-continuation funnel,
        // which would silently resume the task the user just stopped.
        return (
          context: context,
          reliefUsed: true,
          retried: false,
          terminal: await _abortedTurn(context, config, emit),
        );
      }
      if (relieved != null) {
        // The relieved transcript becomes the loop's live context:
        // the retried request is built from it and every later turn
        // rides it (the tuple return hands it back to the host).
        return (
          context: Context(
            systemPrompt: context.systemPrompt,
            messages: relieved,
            tools: context.tools,
          ),
          reliefUsed: true,
          retried: true,
          terminal: null,
        );
      }
    } catch (_) {
      // A failed relief = no relief; the error below is the answer —
      // unless the failure WAS a cancellation (user abort mid-relief,
      // issue #1085): that must surface as aborted, never as the
      // guard error.
      if (_isCancelRequested(cancelToken)) {
        return (
          context: context,
          reliefUsed: true,
          retried: false,
          terminal: await _abortedTurn(context, config, emit),
        );
      }
    }
  }
  return (
    context: context,
    reliefUsed: true,
    retried: false,
    terminal: (
      await _finishWithoutStream(
        context,
        emit,
        _terminalMessage(
          config.model,
          StopReason.error,
          '$contextWindowExhaustedMarker: the outgoing context is '
          '~$tokens tokens, '
          'the ${config.model.id} effective window is $window. The request '
          'was not sent. Auto-compaction runs next; if it keeps failing, '
          'run /compact or start a fresh session.',
        ),
      ),
      context,
    ),
  );
}

/// Whether the host's one-shot over-window relief is still on the table.
bool _reliefAvailable(bool reliefUsed, AgentLoopConfig config) =>
    !reliefUsed && config.overWindowRelief != null;

/// Whether the run was cancelled before its request went out.
bool _isCancelRequested(CancelToken? cancelToken) =>
    cancelToken != null && cancelToken.isCancelled;

/// The already-cancelled turn: no request leaves the loop.
Future<(AssistantMessage, Context)> _abortedTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.aborted, 'Operation aborted'),
    ),
    context,
  );
}

/// A provider/runtime error thrown by the stream call itself becomes an
/// error turn, not a crash.
Future<(AssistantMessage, Context)> _providerErrorTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  Object error,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.error, '$error'),
    ),
    context,
  );
}

/// Builds the synthetic error turn for a provider stream that closed
/// without any terminal event (provider bug): keep the streamed partial
/// when one landed, otherwise synthesize an empty error message.
AssistantMessage _streamEndedWithoutTerminal(
  AgentLoopConfig config,
  AssistantMessage? partial,
) {
  const errorText = 'Provider stream ended without a terminal event';
  return (partial ??
          _terminalMessage(config.model, StopReason.error, errorText))
      .copyWith(stopReason: StopReason.error, errorMessage: errorText);
}

/// Applies the request-payload rewrites before a provider call: the
/// `transformContext` hook and the symmetric tool-pairing repair. Only the
/// request payload is rewritten, never the transcript. Returns the payload
/// plus what the pairing repair changed (empty when nothing did).
Future<(Context, ToolPairingRepairReport)> _buildRequestContext(
  Context context,
  AgentLoopConfig config,
  CancelToken? cancelToken, {
  String? misuseNote,
  int? capCoalesceTarget,
  int? imageCapOverride,
  ImagePayloadRecoveryState? recovery,
}) async {
  // pi applies transformContext (then convertToLlm) before each provider
  // call; only the request payload is rewritten, never the transcript.
  var requestContext = context;
  final transformContext = config.transformContext;
  if (transformContext != null) {
    requestContext = Context(
      systemPrompt: context.systemPrompt,
      messages: await transformContext(List.of(context.messages), cancelToken),
      tools: context.tools,
    );
  }
  // Session image registry (#171): unique history images ride once as
  // `[Image N]` carriers; every other occurrence becomes a text ref.
  // Payload-only rewrite — the transcript is never touched, and the
  // kill switch (`images.registry: false`) skips it entirely. Issue
  // #1750: the cap resolves per model (latched > perModel config >
  // catalog maxImages > the global maxPerRequest) so a request never
  // carries more unique images than the target model accepts. #1889:
  // the host-facing seam is the per-request report (one call per
  // build, zero drops included) — hosts aggregate + latch it into a
  // single user-facing notice; per-image detail stays on the debug
  // surface inside the same report.
  final rewritten = rewriteRequestImages(
    requestContext.messages,
    provider: config.model.provider,
    modelId: config.model.id,
    catalogMaxImages: config.model.maxImages,
    capOverride: imageCapOverride,
    recovery: recovery,
  );
  if (!identical(rewritten, requestContext.messages)) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: rewritten,
      tools: requestContext.tools,
    );
  }
  requestContext = _appendRecoveryNote(requestContext, recovery);
  // gh-1409: compaction-pinned skill operative lines ride every
  // post-boundary request as the verbatim carrier (AC2) — payload-only,
  // the transcript is never touched; the kill switch
  // (`operativePinConfig.enabled = false`) skips it entirely. Runs BEFORE
  // tool-pairing repair: the carrier is a standalone user message and can
  // never break a call/result run (it anchors outside them).
  if (config.operativeSkills.isNotEmpty && operativePinConfig.enabled) {
    // E9: the pin budget shrinks proportionally on tiny windows so pins
    // never crowd out the recent-token working set — an eighth of the
    // effective window, floored at 1024 chars (one 512-char line plus
    // envelope), capped at the configured budget.
    final window = effectiveContextWindow(
      config.model.contextWindow,
      config.contextWindowCap,
    );
    final budgetChars = min(
      operativePinConfig.budgetChars ?? defaultPinBudgetChars,
      // E9: at most an eighth of the effective window, floored at 1024
      // chars (one 512-char line plus envelope) — a large window keeps the
      // full default budget, a tiny one shrinks the pins proportionally.
      max(window ~/ 8, 1024),
    );
    final injected = injectOperativePinCarriers(
      requestContext.messages,
      skills: config.operativeSkills,
      budgetChars: budgetChars,
      onNotice: operativePinNotice,
    );
    if (!identical(injected, requestContext.messages)) {
      requestContext = Context(
        systemPrompt: requestContext.systemPrompt,
        messages: injected,
        tools: requestContext.tools,
      );
    }
  }
  // Broken tool pairing (orphan results at any position, displaced results,
  // duplicate ids, unanswered calls) makes providers hard-400 EVERY
  // subsequent request; repair the payload, never the transcript.
  // gh-1449: already-reported orphans drop silently; fresh ones are noted
  // once. gh-2270: the latch does NOT fire here — a built request can
  // still be terminal-refused (over-window) or thrown away pre-wire, and a
  // request that never streamed must not consume the one-shot. The keys
  // latch at delivery — the first stream event, in [_streamAttempt].
  final repaired = repairToolPairing(
    requestContext.messages,
    reportedOrphanKeys: config.reportedOrphanKeys ?? const <String>{},
  );
  if (!identical(repaired.messages, requestContext.messages)) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: repaired.messages,
      tools: requestContext.tools,
    );
  }
  // gh-1680: armed cap repair coalesces the payload; AC7 keeps the transcript untouched.
  requestContext = _applyMessageCapCoalesce(requestContext, capCoalesceTarget);
  // gh-1556: an armed session deadline rides every request payload as a
  // trailing `time-left:` line — a standalone user message, so it can
  // never break a call/result run (same seat as the misuse note below).
  // Payload-only: the transcript is never touched, and a null provider
  // result (deadline unset/cleared) keeps the request byte-for-byte.
  final budgetLine = config.budgetLineProvider?.call();
  if (budgetLine != null) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: [...requestContext.messages, UserMessage.text(budgetLine)],
      tools: requestContext.tools,
    );
  }
  // Issue #862: an armed corrective note rides the NEXT request payload as
  // a trailing user message — visible to the model, never in the transcript.
  // Drained ONCE by the caller ([_streamAssistantResponse], before the
  // attempt loop) and re-attached on every rebuild, so an over-window
  // retry cannot silently drop an already-armed note (issue #862 review).
  if (misuseNote != null) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: [...requestContext.messages, UserMessage.text(misuseNote)],
      tools: requestContext.tools,
    );
  }
  return (requestContext, repaired.report);
}

/// Builds the outbound-request capture emitted with [ModelRequestEvent]
/// (issue #385): the cheap summary (message count/sizes, tool names,
/// bounded previews), the per-message block structure (F3), the full
/// system-prompt blob (F1), the complete tool-manifest blob (F2), and —
/// when [config.wireDump] is on — the RAW serialized request payload (F5;
/// hosts redact and cap before persisting).
ModelRequestEvent _captureRequest(AgentLoopConfig config, Context context) {
  final messages = [
    for (final message in context.messages)
      TrajectoryRequestMessageSummary(
        role: message.role,
        // Unserializable arguments degrade to the placeholder instead of
        // throwing mid-loop (issue #385 E3: never a crash).
        chars: _safeJsonEncode(message.toJson()).length,
        preview: _requestPreview(message),
        blocks: _requestBlocksOf(message),
      ),
  ];
  final tools = context.tools ?? const <Tool>[];
  final prompt = context.systemPrompt;
  final promptBlob = prompt == null || prompt.isEmpty
      ? null
      : TrajectoryPromptBlob.of(prompt);
  final manifestBlob = tools.isEmpty
      ? null
      : TrajectoryToolManifestBlob.of(tools);
  return ModelRequestEvent(
    // gh-1073: the per-message detail is capped to the newest tail — an
    // unbounded summary of a 1000-message request is what grew the ledger
    // records to ~0.5 MB each.
    detail: capTrajectoryRequestDetail(
      TrajectoryRequestDetail(
        messageCount: messages.length,
        systemPromptChars: prompt?.length ?? 0,
        toolCount: tools.length,
        toolNames: [for (final tool in tools) tool.name],
        messages: messages,
        systemPromptHash: promptBlob?.hash,
        toolManifestHash: manifestBlob?.hash,
      ),
    ),
    promptBlob: promptBlob,
    manifestBlob: manifestBlob,
    rawWireDump: config.wireDump ? trajectoryWireDumpPayload(context) : null,
  );
}

/// Block structure of one outbound request message (F3): bounded full
/// texts and `[image WxH]` markers per content block, in request order.
List<TrajectoryRequestMessageBlock> _requestBlocksOf(Message message) {
  final List<ContentBlock> blocks = switch (message) {
    UserMessage(:final content) =>
      content is String
          ? [TextContent(text: content)]
          : List<ContentBlock>.of(content as List<ContentBlock>),
    AssistantMessage(:final content) => content,
    ToolResultMessage(:final content) => content,
    _ => const <ContentBlock>[],
  };
  return trajectoryRequestBlocks(blocks);
}

/// [jsonEncode] that never throws (cyclic/unserializable values degrade
/// to a placeholder).
String _safeJsonEncode(Object? value) {
  try {
    return jsonEncode(value);
  } catch (_) {
    return '[unserializable]';
  }
}

/// Bounded plain-text preview of a request message
/// (~[requestPreviewChars] characters).
String _requestPreview(Message message) {
  final text = switch (message) {
    UserMessage(:final content) => textPayloadOf(content),
    AssistantMessage(:final content) => textPayloadOf(content),
    ToolResultMessage(:final content) => textPayloadOf(content),
    _ => '',
  };
  return text.length <= requestPreviewChars
      ? text
      : '${text.substring(0, requestPreviewChars)}…';
}

/// Finalizes the streamed terminal event into the context. The finished
/// message's tool-call ids are first made session-unique (issue #85:
/// some providers emit per-run position counters like `bash_198` that reset
/// every run — ids are stamped against everything already in the transcript
/// so replay/trim/branch can never put duplicate ids into one request).
Future<AssistantMessage> _finishStreamed(
  Context context,
  AgentEventSink emit,
  bool addedPartial,
  AssistantMessageEvent terminalEvent,
) async {
  var finalMessage = terminalEvent.partial;
  finalMessage = _stampSessionUniqueToolCallIds(
    finalMessage,
    context,
    skipLast: addedPartial,
  );
  if (addedPartial) {
    context.messages[context.messages.length - 1] = finalMessage;
  } else {
    context.messages.add(finalMessage);
    await emit(MessageStartEvent(finalMessage));
  }
  await emit(MessageEndEvent(finalMessage));
  return finalMessage;
}

/// Renames any [ToolCall] id of [message] that already appears in the
/// transcript (or twice within [message] itself) to `<id>_2`, `<id>_3`, ….
/// Ids are opaque to tools and providers echo them back verbatim, so only
/// generation changes. Collisions with ids the context never sees are
/// harmless; collisions inside one context are what break pairing.
AssistantMessage _stampSessionUniqueToolCallIds(
  AssistantMessage message,
  Context context, {
  required bool skipLast,
}) {
  if (!message.content.any((block) => block is ToolCall)) return message;
  final end = context.messages.length - (skipLast ? 1 : 0);
  return _stampAgainstUsed(
    message,
    _transcriptToolCallIds(context.messages, end),
  );
}

/// The rename core of [_stampSessionUniqueToolCallIds] against a
/// caller-owned [used] set (mutated: every id, original or fresh,
/// registers). Shared by the final-message pass and the per-partial pass in
/// [_consumeResponseStream] so both produce the same ids for one stream.
AssistantMessage _stampAgainstUsed(AssistantMessage message, Set<String> used) {
  var changed = false;
  final content = <ContentBlock>[];
  for (final block in message.content) {
    if (block is! ToolCall) {
      content.add(block);
      continue;
    }
    final renamed = _freshToolCallId(block, used);
    changed = changed || !identical(renamed, block);
    content.add(renamed);
  }
  return changed ? message.copyWith(content: content) : message;
}

/// Collects every tool-call id visible in `messages[0, end)`: ids of calls
/// inside assistant messages and ids of the results answering them.
Set<String> _transcriptToolCallIds(List<Message> messages, int end) {
  final used = <String>{};
  for (var i = 0; i < end; i++) {
    switch (messages[i]) {
      case AssistantMessage(:final content):
        for (final block in content) {
          if (block is ToolCall) used.add(block.id);
        }
      case ToolResultMessage(:final toolCallId):
        used.add(toolCallId);
      default:
        break;
    }
  }
  return used;
}

/// Returns [call] unchanged (registered in [used]) when its id is free,
/// otherwise renamed to the first free `<id>_2`, `<id>_3`, … which is then
/// registered too.
ToolCall _freshToolCallId(ToolCall call, Set<String> used) {
  if (!used.contains(call.id)) {
    used.add(call.id);
    return call;
  }
  var k = 2;
  var fresh = '${call.id}_$k';
  while (used.contains(fresh)) {
    k++;
    fresh = '${call.id}_$k';
  }
  used.add(fresh);
  return call.copyWith(id: fresh);
}

/// Appends (or replaces the partial with) [message] and emits its lifecycle
/// events, for paths where no provider events flowed.
Future<AssistantMessage> _finishWithoutStream(
  Context context,
  AgentEventSink emit,
  AssistantMessage message, {
  bool replaceLast = false,
}) async {
  if (replaceLast) {
    context.messages[context.messages.length - 1] = message;
  } else {
    context.messages.add(message);
    await emit(MessageStartEvent(message));
  }
  await emit(MessageEndEvent(message));
  return message;
}

AssistantMessage _terminalMessage(
  Model model,
  StopReason stopReason,
  String errorMessage,
) {
  return AssistantMessage(
    content: const [],
    api: model.api,
    provider: model.provider,
    model: model.id,
    usage: Usage.zero,
    stopReason: stopReason,
    errorMessage: errorMessage,
    timestamp: DateTime.now(),
  );
}

/// Fails all tool calls from an assistant message that was truncated by the
/// output token limit. Streamed tool-call arguments are finalized with a
/// best-effort JSON salvage parser, so a truncated message can yield tool
/// calls whose arguments parse but are silently incomplete. None of them are
/// safe to execute; report each as an error so the model can re-issue them.
///
/// Port of pi's `failToolCallsFromTruncatedMessage`.
Future<_ExecutedToolCallBatch> _failToolCallsFromTruncatedMessage(
  List<ToolCall> toolCalls,
  AgentEventSink emit, {
  AgentLoopConfig? config,
}) async {
  final messages = <ToolResultMessage>[];
  for (final toolCall in toolCalls) {
    // Issue #1829 Core flow B: a non-executing capture side path may
    // persist salvage-parsed deliverable text BEFORE the failure is
    // reported (fail-closed: still failed unexecuted; awaited so the
    // capture re-seeds the durable ids before its persist, gh-1956).
    await config?.onTruncatedToolCall?.call(toolCall);
    await emit(
      ToolExecutionStartEvent(
        toolCallId: toolCall.id,
        toolName: toolCall.name,
        args: toolCall.arguments,
        timestamp: DateTime.now(),
      ),
    );
    final finalized = _FinalizedToolCall(
      toolCall,
      _errorToolResult(
        'Tool call "${toolCall.name}" was not executed: the response hit '
        'the output token limit, so its arguments may be truncated. '
        'Re-issue the tool call with complete arguments.',
      ),
      true,
    );
    await _emitToolExecutionEnd(finalized, emit);
    messages.add(await _emitToolResultMessage(finalized, emit));
  }
  return _ExecutedToolCallBatch(messages, terminate: false);
}

/// Executes the tool calls of one assistant message. Port of pi's
/// `executeToolCalls`, including the per-tool `executionMode` override: if
/// any called tool is an [AgentTool] with
/// [AgentTool.executionMode] == [ToolExecutionMode.sequential], the whole
/// batch runs sequentially (pi semantics).
Future<_ExecutedToolCallBatch> _executeToolCalls(
  Context context,
  AssistantMessage assistantMessage,
  List<ToolCall> toolCalls,
  AgentLoopConfig config,
  ToolExecutor toolExecutor,
  CancelToken? cancelToken,
  AgentEventSink emit,
) {
  final hasSequentialToolCall = toolCalls.any((toolCall) {
    final tool = _findTool(context, toolCall.name);
    return tool is AgentTool &&
        tool.executionMode == ToolExecutionMode.sequential;
  });
  return config.toolExecution == ToolExecutionMode.sequential ||
          hasSequentialToolCall
      ? _executeToolCallsSequential(
          context,
          assistantMessage,
          toolCalls,
          config,
          toolExecutor,
          cancelToken,
          emit,
        )
      : _executeToolCallsParallel(
          context,
          assistantMessage,
          toolCalls,
          config,
          toolExecutor,
          cancelToken,
          emit,
        );
}

Future<_ExecutedToolCallBatch> _executeToolCallsSequential(
  Context context,
  AssistantMessage assistantMessage,
  List<ToolCall> toolCalls,
  AgentLoopConfig config,
  ToolExecutor toolExecutor,
  CancelToken? cancelToken,
  AgentEventSink emit,
) async {
  final finalizedCalls = <_FinalizedToolCall>[];
  final messages = <ToolResultMessage>[];

  for (final toolCall in toolCalls) {
    await emit(
      ToolExecutionStartEvent(
        toolCallId: toolCall.id,
        toolName: toolCall.name,
        args: toolCall.arguments,
        timestamp: DateTime.now(),
      ),
    );

    final finalized = switch (await _prepareToolCall(
      context,
      assistantMessage,
      toolCall,
      config,

