    _toolsAvailability = AgentToolAvailability(
      agent: _agent,
      tools: stack.registry.tools,
      onDevice: isOnDevice,
      registry: stack.registry,
      initialConfig: initialToolsConfig ?? const ToolsConfig(),
      // yaml `tools:` scopes under the runtime store (AC2/E1).
      configScopes: [
        if (appConfig case final s?) (ToolScope.global, s.userTools),
        if (appConfig case final s?) (ToolScope.project, s.projectTools),
      ],
      loadMode: appConfig?.loadMode ?? AgentLoadMode.defaultMode,
      rebuildPrompt: () {
        _agent.state.systemPrompt = _composeSystemPrompt(config);
      },
    );
    // Durable facts from past sessions join the prompt asynchronously
    // (memory stores initialize lazily; recompose on arrival).
    unawaited(_refreshMemorySection());
    // gh-1444 E3: the Keys settings section is the production revocation
    // path — a delete there revokes the live value (the roster keeps the
    // name visible as ABSENT) and a re-save re-injects it.
    if (_sessionKeys != null) {
      for (final name in _sessionKeys.names) {
        final value = _sessionKeys.valueOf(name);
        if (value != null && value.isNotEmpty) _storeSecretNames.add(name);
      }
      _sessionKeys.addListener(_reconcileSessionKeySecrets);
    }
    // Issue #2156 P1: provider→live-model linkage. The office add-in
    // (and every post-onboarding home) boots a placeholder session; a
    // provider added to the registry afterwards (or its key, minted by a
    // sign-in) never reached the live chat. Listen for the registry
    // change — and check once at boot, so a restart with a keyed registry
    // lands on the provider without a picker visit.
    if (providerRegistry != null) {
      providerRegistry.addListener(_applyLinkedProvider);
      unawaited(_applyLinkedProvider());
    }
  }

