  Future<List<(String, String)>> observeSubagent(
    String id, {
    int tail = 20,
  }) async {
    final handle = _subagentManager?[id];
    if (handle == null) return const [];
    try {
      return await _observeSubagentSessionTail(handle, tail);
    } on Object {
