/// Per-drain liveness bookkeeping for gh-1459 ask #4: the quiet cadence
/// knob plus, per job, the last quiet bucket consumed (steered or
/// skipped) and the probe generation seen at that consumption.
/// Generation counters, not timestamps — the comparison stays valid
/// under a fake DateTime test clock.
final class _HeadlessDrainLiveness {
  _HeadlessDrainLiveness(this.quietMs);

  /// `headless.shellJobQuietMs`; `0` disables the interim steers.
  final int quietMs;
  final consumedBucket = <String, int>{};
  final seenProbeGen = <String, int>{};

  /// The next drain wake bound: [deadline] pulled earlier by the next
  /// liveness threshold of any active shell job, so a due notice fires
  /// on cadence even while the job keeps running. Pure time arithmetic
  /// on the waiting clock — unit-tested through the drain ITs.
  Duration wakeIn(List<ShellJobEntry> active, DateTime now, DateTime deadline) {
    var wake = deadline.difference(now);
    if (quietMs <= 0 || active.isEmpty) return wake;
    for (final job in active) {
      final bucket = (consumedBucket[job.id] ?? 0) + 1;
      final due = job.startedAt.add(Duration(milliseconds: quietMs * bucket));
      final d = due.difference(now);
      if (d < wake) wake = d;
    }
    return wake;
  }
}

/// The warm-switch resumed-context cache (gh-1734 root cause 3): a
/// session whose file is unchanged since its last open reuses the built
/// [SessionContext] instead of re-paying the projection walk on every
/// open/switch. Entries are keyed by (path, sizeBytes, mtimeMs, variant);
/// any change to the file (append, rotation, truncate) produces a
/// different fingerprint and a clean miss, and the caller-supplied
/// [variant] separates builds whose meaning changed (the resume budget
/// bounds how much history a build carries).
library;

import '../session/session_tree.dart';

/// One memoized context build with the stat fingerprint it was built at.
final class _Entry {
  _Entry({
    required this.sizeBytes,
    required this.mtimeMs,
    required this.variant,
    required this.context,
  });

  final int sizeBytes;
  final int mtimeMs;
  final int variant;
  final SessionContext context;
}

/// LRU-bounded per-process cache of built session contexts.
///
/// The CLI holds one instance for the process lifetime (contexts are
/// rebuilt from the session file, so a process-wide cache is consistent
/// with every writer: a foreign append changes the file's stat and the
/// entry misses). [match] hands out a fresh message list per hit — a
/// consumer mutating its copy never corrupts the cache, and the cached
/// message objects themselves must be treated as immutable (the session
/// layer never mutates projected messages in place).
final class ResumedContextCache {
  /// Creates a cache holding at most [capacity] sessions (≥ 1).
  ResumedContextCache({int capacity = 4})
    : capacity = capacity < 1 ? 1 : capacity;

  /// Maximum number of sessions kept resident.
  final int capacity;

  final Map<String, _Entry> _entries = {};

  /// Number of cached sessions.
  int get length => _entries.length;

  /// The context built for [path] when the file still has exactly
  /// ([sizeBytes], [mtimeMs]) and the same build [variant]. The returned
  /// context carries a fresh message list; the entry is refreshed as the
  /// most recently used. A stale probe does not evict the entry (the
  /// caller rebuilds and re-remembers over it).
  SessionContext? match(
    String path, {
    required int sizeBytes,
    required int mtimeMs,
    int variant = 0,
  }) {
    final entry = _entries[path];
    if (entry == null) return null;
    if (entry.sizeBytes != sizeBytes ||
        entry.mtimeMs != mtimeMs ||
        entry.variant != variant) {
      return null;
    }
    _entries.remove(path);
    _entries[path] = entry;
    return SessionContext(
      messages: List.of(entry.context.messages),
      thinkingLevel: entry.context.thinkingLevel,
      model: entry.context.model,
      activeToolNames: entry.context.activeToolNames == null
          ? null
          : List.of(entry.context.activeToolNames!),
    );
  }

  /// Remembers [context] as the build for [path] at the given fingerprint
  /// and [variant].
  void remember(
    String path, {
    required int sizeBytes,
    required int mtimeMs,
    required SessionContext context,
    int variant = 0,
  }) {
    _entries.remove(path);
    _entries[path] = _Entry(
      sizeBytes: sizeBytes,
      mtimeMs: mtimeMs,
      variant: variant,
      context: context,
    );
    while (_entries.length > capacity) {
      _entries.remove(_entries.keys.first);
    }
  }

  /// Drops every entry.
  void clear() => _entries.clear();
}

  /// session was last active.
