116:/// The aligned record aliases of a transcript plus the epoch index they
117:/// resolve against — `null` marks a non-record (level-0 tail blocks,
118:/// instructions, notices) AND the live edge (messages appended since the
119:/// epoch started: untaged until the next epoch).
120:final class TranscriptSeqMap {
121:  /// Creates the map of one tag epoch: [headSeqs] aligned to the
122:  /// projected transcript head, [index] the epoch's file-order snapshot.
123:  const TranscriptSeqMap({required this.headSeqs, required this.index});
124:
125:  /// The seqs of the projected head, aligned by message index (`null` =
126:  /// a non-record). Treated as read-only by every consumer.
127:  final List<int?> headSeqs;
128:
129:  /// The epoch's record index (seq → record). Frozen at epoch start: an
130:  /// id beyond it never resolves, so a mis-predicted live-edge alias
131:  /// cannot hide someone else's record.
132:  final RecordSeqIndex index;
133:
134:  /// Number of head messages (the projected transcript at epoch start).
135:  int get headLength => headSeqs.length;
136:
137:  /// The alias of the message at [position]: exact on the head (the
138:  /// epoch's records), `null` beyond it — the live edge carries no tag
139:  /// (the epoch rule: a message becomes addressable when the NEXT epoch's
140:  /// projection makes it a record) — and `null` for a non-record.
141:  int? seqAt(int position) {
142:    if (position < 0 || position >= headSeqs.length) return null;
143:    return headSeqs[position];
144:  }
145:
146:  /// The stable record id the alias at [position] resolves to on the
147:  /// epoch index — `null` for non-records, the live edge and unknown
148:  /// aliases.
149:  String? recordIdAt(int position) {
150:    final seq = seqAt(position);
151:    if (seq == null) return null;
152:    final record = index.recordAt(seq);
153:    return record?.id;
154:  }
