80:  /// A user turn started (hosts call it at every prompt).
81:  void onTurn() => _turns++;
82:
83:  /// A compaction run happened (success or failure alike — the band
84:  /// must not re-fire every turn over a failing endpoint).
85:  void recordRun() => _turnsAtRun = _turns;
