849:        // no-work terminal, identical to a null preparation.
850:        if (_isEmptyFoldableRegionRefusal(error)) {
851:          return _AttemptOutcome(
852:            ok: true,
853:            error: null,
854:            noWork: true,
855:            summary: null,
856:            hiddenRecords: 0,
857:            summarizedMessages: 0,
858:          );
859:        }
860:        // A cancelled summarizer call never reaches this catch as a raw
861:        // CancelledException — compactSession converts every summarizer
862:        // failure (issue #2263). Cancellation surfaces through the run
863:        // token instead: the `_runPass` trim-valve guard below rethrows
864:        // it off any `ok: false`, and `run()`'s finally belt catches the
865:        // rest (#1085).
866:        final errorText = error.toString();
867:        final isTransient = _transient.hasMatch(errorText);
868:        // Issue #729 AC2: an overflow-classified failure is DETERMINISTIC —
869:        // the payload cannot fit this endpoint no matter how often it is
870:        // retried. Route immediately to the next summarizer / the local
871:        // trim with ZERO backoff retries, even when the provider wraps the
872:        // 400 in a transient-shaped message.
873:        final isOverflow = _overflow.hasMatch(errorText);
874:        if (isOverflow || attempt >= maxAttempts || !isTransient) {
875:          return _AttemptOutcome(
876:            ok: false,
877:            error: error,
878:            noWork: false,
879:            summary: null,
880:            hiddenRecords: 0,
881:            summarizedMessages: 0,
882:          );
883:        }
884:        final backoff = baseBackoff * attempt;
885:        hooks.onRetry(attempt, maxAttempts, backoff, error);
886:        await Future<void>.delayed(backoff);
887:      }
888:    }
889:    return _AttemptOutcome(
890:      ok: false,
891:      error: StateError('unreachable: compact attempt loop'),
892:      noWork: false,
893:      summary: null,
894:      hiddenRecords: 0,
895:      summarizedMessages: 0,
896:    );
897:  }
