899:  /// Counts the records hidden behind [record]'s compaction boundary and
900:  /// the message records folded into its summary — one branch walk, ids
901:  /// only (never positions).
902:  Future<(int, int)> _compactionCounts(CompactionRecord record) async {
903:    final path = await session.getBranch();
904:    final keptIndex = path.indexWhere((e) => e.id == record.firstKeptEntryId);
905:    final hidden = keptIndex <= 0 ? 0 : keptIndex;
906:    var summarized = 0;
907:    for (final entry in path.take(hidden)) {
908:      if (entry is MessageRecord) summarized++;
909:    }
910:    return (hidden, summarized);
