961:/// The mechanical over-window valve, host-callable (the resume boot cap
962:/// applies it INSTANTLY when a resumed transcript cannot fit the window:
963:/// an LM compaction pass there takes minutes on slow providers and blocks
964:/// the whole boot — the goal_builder incident). Semantics are exactly
965:/// [_localTrimFallback]'s; see there for the contract.
966:({List<Message> messages, int dropped})? localTrimValve({
967:  required List<Message> messages,
968:  required String reason,
969:  required int window,
970:  required CompactionSettings settings,
971:  required int overheadTokens,
972:}) {
973:  if (messages.isEmpty) return null;
974:  // gh-1425: the valve must land UNDER the compaction trigger, not
975:  // merely at keepRecentTokens — a keepRecent-sized tail plus the
976:  // system-prompt/tool-schema overhead can sit above
977:  // `window - reserveTokens`, so the next turn's auto-compact re-fires
978:  // immediately and, with both summarizers still down, the session is
979:  // stuck again (the exact marathon-resume cliff this valve exists
980:  // for). Clamp the kept budget to the trigger minus the per-request
981:  // overhead; keepRecentTokens still wins when it is smaller. Three
982:  // edge guards (gh-1425 review + flutter_app IT-2):
983:  // - reserve the [context trimmed] marker's own tokens (~64) so the
984:  //   kept region plus marker still lands under the trigger;
985:  // - floor the clamp at the newest message's tokens — a degenerate
986:  //   overhead (≥ the trigger) must still trim SOMETHING, never return
987:  //   an empty window (the projectedBranchBudgetCut rule);
988:  // - but only up to keepRecentTokens: a newest message LARGER than
989:  //   keepRecentTokens must keep the budget AT keepRecentTokens so the
990:  //   walk still finds "nothing droppable" and returns null — that
991:  //   null is the failure the summarizer-ladder exhaustion surfaces
992:  //   (gh-1077 AC2: the app's fix-location notice fires on it, and the
993:  //   transcript stays intact instead of silently dropping the user's
994:  //   newest turn).
995:  final overhead = overheadTokens;
996:  final budget = math.min(
997:    settings.keepRecentTokens,
998:    math.max(
999:      math.max(0, window - settings.reserveTokens - overhead - 64),
1000:      estimateTokens(messages.last), // never an empty window
1001:    ),
1002:  );
1003:  var cut = 0; // first kept index
1004:  var accumulated = 0;
1005:  for (var i = messages.length - 1; i >= 0; i--) {
1006:    accumulated += estimateTokens(messages[i]);
1007:    if (accumulated > budget) {
1008:      cut = i + 1;
1009:      break;
1010:    }
1011:  }
1012:  if (cut <= 0) return null;
1013:  final kept = messages.sublist(cut);
1014:  if (kept.isEmpty) return null;
1015:  // Pairing integrity (issue #85): a token-boundary cut can land between
1016:  // an assistant tool call and its result, leaving an orphaned result at
1017:  // ANY position of the kept region — the production wedge survived the
1018:  // old leading-only skip as the second block of a merged wire message
1019:  // (`messages.0.content.1`). The request-boundary repairer is the single
1020:  // generalization: drops orphan results (with a visible note),
1021:  // synthesizes missing results, hoists displaced ones. In-memory only —
1022:  // the session file keeps every record.
1023:  final rebuilt = repairToolPairing([
1024:    UserMessage.text(
1025:      '$localTrimMarkerPrefix $reason, '
1026:      '$cut older message(s) were dropped from the live context at '
1027:      '${DateTime.now().toUtc().toIso8601String()} — the full history '
1028:      'stays in the session file]',
1029:    ),
1030:    // Zero the kept generations' usage anchors — a stale generation-time
1031:    // anchor would keep the estimate over the window and retrigger the
1032:    // compactor on the next turn (same rule as the success pass).
1033:    for (final message in kept)
1034:      if (message is AssistantMessage)
1035:        message.copyWith(usage: Usage.zero)
1036:      else
1037:        message,
1038:  ]);
1039:  return (messages: rebuilt.messages, dropped: cut);
1040:}
