93:class _AutoCompactorCliHooks implements AutoCompactorHooks {
94:  _AutoCompactorCliHooks(this.cli, {required this.auto});
95:
96:  final AgentCli cli;
97:
98:  /// Whether this run is the auto-trigger (vs the manual `/compact`): the
99:  /// report header names what happened — a manual compact must not read
100:  /// as "auto-compacted".
101:  final bool auto;
102:
103:  /// Whether [onPass] rendered a real report block this run — the
104:  /// manual-compact no-op note must not fire over a printed report.
105:  bool reportedPass = false;
106:
107:  DateTime? _lastDeltaPhase;
108:  String _compactionTail = '';
109:
110:  /// Whether [onDelta] streamed dimmed summary bytes on the log face
111:  /// (gh-1433 E4): the next compaction-facing line closes the stream
112:  /// line first, so the report never glues onto the live summary.
113:  bool _deltaStreamed = false;
114:
115:  /// Closes the E4 live-summary stream line (one newline on the primary
116:  /// channel) before the next compaction-facing output lands.
117:  void _closeDeltaStreamLine() {
118:    if (!_deltaStreamed) return;
119:    _deltaStreamed = false;
120:    cli.io.write('\n');
121:  }
122:
123:  @override
124:  void onDelta(String delta) {
125:    // gh-1636: the summary being written is internal checkpoint text —
126:    // echoing every delta onto the headless log buries the actual reply
127:    // the same way the full report block did. Hidden by default; the
128:    // gh-1430 E3 tier-2 `… reasoning Ns` line (armed around the whole
129:    // compaction window) keeps the wait visible without the dump.
130:    // `tui.showCompactionDetails` restores the gh-1433 E4 live stream.
131:    if (cli._logIsUi) {
132:      if (!cli.config.showCompactionDetails) return;
133:      cli.io.write(cli._style.dim(cli._redactRendered(delta)));
134:      _deltaStreamed = true;
135:      return;
136:    }
137:    // Live tail of the summary being written, shown in the busy row so
138:    // compaction reads as work, not a hang. Throttled — deltas are hot.
139:    final merged = (_compactionTail + delta).replaceAll('\n', ' ');
140:    _compactionTail = _rollingTail(merged);
141:    final now = DateTime.now();
142:    final last = _lastDeltaPhase;
143:    if (last != null &&
144:        now.difference(last) < const Duration(milliseconds: 150)) {
145:      return;
146:    }
147:    _lastDeltaPhase = now;
148:    cli._pushBusyPhase('Compacting context… $_compactionTail');
149:  }
150:
151:  @override
152:  void onAttemptStart(String label, int attempt, Duration budget) {
153:    _closeDeltaStreamLine();
154:    // A slow/dead summarizer endpoint must read as a bounded wait, not a
155:    // silent hang: name the endpoint being tried and its time cap.
156:    cli._tuiController?.setBusyPhase(
157:      'Compacting context… $label (attempt $attempt, '
158:      '${budget.inSeconds}s cap)',
159:    );
160:    _compactionTail = '';
161:    _lastDeltaPhase = null;
162:  }
163:
164:  /// The last 60 chars of the merged tail (newlines flattened) — a helper
165:  /// so [onDelta] stays at the repo's CC gate.
166:  static String _rollingTail(String merged) =>
167:      merged.length > 60 ? merged.substring(merged.length - 60) : merged;
168:
169:  @override
170:  void onPass(AutoCompactorPass pass) {
171:    _closeDeltaStreamLine();
172:    _runTokensBefore ??= pass.tokensBefore;
173:    // Honest pass accounting for the funnel's `passesRan` trim gate
174:    // (issue #2273): only pass receipts count — a zero-pass run (the
175:    // under-trigger short-circuit) leaves the counter untouched, so the
176:    // gate never reads non-runs as passes.
177:    cli._compactionPassesStarted++;
178:    // gh-2044: the escalation's numeric reason rides the diagnostic line
179:    // — counts only (settled tokens, margin, band, hideables left), never
180:    // rendered ledger/message content. Absent on every other pass kind,
181:    // so existing lines stay byte-identical.
182:    final escalationCounts = pass.marginTokens == null
183:        ? ''
184:        : 'margin=${pass.marginTokens} '
185:              'band=${pass.bandTokens} '
186:              'hideable-left=${pass.hideableRemaining ?? 0} ';
187:    if (pass.fallback == 'structured·skipped-judge-latch') {
188:      // Issue #2274: a DESIGNED judge-latch skip, not a failure — the
189:      // judge contributes nothing this run by design and the
190:      // deterministic hide's own receipt follows. Rendering the skip as
191:      // FAILED made fa.log read as a persistent compaction failure for
192:      // the whole probe window while sessions progressed fine.
193:      cli._logDiagnostic(
194:        'auto-compact pass ${pass.pass} judge-latch skip '
195:        'sid=${cli._logSid} '
196:        'tokens ${pass.tokensBefore}→${pass.tokensAfter} '
197:        'error=${pass.error ?? '-'}',
198:      );
199:      return;
200:    }
201:    if (!pass.ok) {
202:      // The pass failed: onBothRolesFailed already prints the user-facing
203:      // hint. Printing the success-looking "auto-compacted" line here
204:      // claimed context was summarized when nothing was.
205:      cli._logDiagnostic(
206:        'auto-compact pass ${pass.pass} FAILED sid=${cli._logSid} '
207:        'tokens ${pass.tokensBefore}→${pass.tokensAfter} '
208:        '$escalationCounts'
209:        'error=${pass.error ?? '-'}',
210:      );
211:      return;
212:    }
213:    if (pass.fallback == 'local-trim') {
214:      // Mechanical in-memory trim (summarizer down): honest wording, no
215:      // "summarized" claim.
216:      cli.io.writeln(
217:        '[context trimmed] ${pass.tokensBefore} → ${pass.tokensAfter} '
218:        'tokens (summarizer unavailable — kept the most recent messages '
219:        'locally; the session file keeps the full history)',
220:      );
221:      cli._logDiagnostic(
222:        'auto-compact pass ${pass.pass} local-trim sid=${cli._logSid} '
223:        'tokens ${pass.tokensBefore}→${pass.tokensAfter}',
224:      );
225:      return;
226:    }
227:    if (pass.tokensAfter == pass.tokensBefore &&
228:        pass.hiddenRecords == 0 &&
229:        pass.summarizedMessages == 0) {
230:      // No-op pass (already compacted at the leaf): nothing changed —
231:      // stay quiet instead of printing a fake "N tokens summarized".
232:      // Honest zeros print only when nothing happened; a pass that hid
233:      // or summarized records prints even on a flat token estimate
234:      // (issue #438 E3).
235:      cli._logDiagnostic(
236:        'auto-compact pass ${pass.pass} no-op sid=${cli._logSid}',
