1010:    if (runToken != null) {
1011:      unawaited(
1012:        runToken.onCancel.then((_) => abort.cancel(runToken.cancelReason)),
1013:      );
1014:    }
1015:    try {
1016:      return await _runAutoCompactWithToken(
