128:  /// compaction of an already-over-window transcript.
129:  Future<void> _beginUserPrompt({required bool isAutoContinue}) async {
130:    // GOAL #2394: the engine setting decides whether this turn's requests
131:    // carry record tags (structured only) — before the pre-flight
132:    // compaction so a merged hand-over sees the same policy.
133:    _syncRecordTags();
134:    // GOAL #2394 (D8/D9): a user turn advanced the hysteresis clock; a
135:    // post-run hand-over still in flight is AWAITED here so its records
136:    // land before this turn's pre-flight measures the transcript.
137:    if (!isAutoContinue) _handOverTrigger.onTurn();
138:    await _handOverTrigger.gate.wait();
139:    // Wall-clock catch-up (issue #259): records that came due while the
140:    // host slept (or while no tick ran) are delivered HERE, at turn start —
141:    // awaited before the prompt so this turn's first steering poll already
142:    // sees the fired reminder, instead of waiting for the next timer tick.
143:    try {
144:      if (await _scheduledMessages.deliverDue() > 0) {
145:        unawaited(_pushScheduledStatus());
146:      }
147:    } on Object {
148:      // Best-effort: a broken sweep must never block a turn.
149:    }
150:    if (isAutoContinue) return;
151:    _overWindowAutoResumed = false;
152:    // A fresh user text clears the over-window badge: the new run starts
153:    // clean, and only THIS run's folds may badge it (issue #438 E1).
154:    _autoFoldCount = 0;
155:    // A fresh user action opens a NEW dedup episode (issue #2119 AC1): the
156:    // user re-invoking the same request re-renders its failure honestly.
157:    _lastProviderErrorKey = null;
158:    // One empty-reply nudge per logical turn (issue #1085 M2b).
159:    _emptyReplyNudgesLeft = 1;
160:    // The stuck-call nudge budget refills per turn (issue #1185 E2).
161:    _waiting.resetToolNudges();
162:    // The user's explicit stop ends with the turn that was stopped
163:    // (issue #1085 round-1): a fresh prompt re-arms the funnel's abort
164:    // gate.
165:    _runAbortRequested = false;
