351:  Future<void> _afterRun() async {
352:    // A TTSR abort/inject/retry chain may still be in flight when the
353:    // aborted run settles; persist only once the whole chain completed.
354:    await _ttsr?.settled;
355:    _hubCompletePanels();
356:    await _persistMessages();
357:    // gh-1590: a run finalize gives the job board a chance to land its
358:    // snapshot — UNFORCED, inside the persist window: the drain path
359:    // completes one run per settle notice, and a force here would append
360:    // one record per reaction run, defeating the coalescing. The final
361:    // state rides the trailing leg or the shutdown flush instead; when
362:    // the window is open the gate skips the encode entirely.
363:    await _persistJobBoard();
364:    try {
365:      // GOAL #2394 (D9): the post-run call runs under the `compacting`
