303:    // per run with the net freed delta (clamped — a restamped estimator
304:    // can report a slightly larger after-count than the usage-anchored
305:    // before-count). Zero-pass runs (issue #2273): no pass receipt means
306:    // no before-count — the bracket still closes with freed 0, or the
307:    // next turn's time is attributed to a compaction that never ran.
308:    final before = _runTokensBefore;
309:    final freed = before == null ? 0 : before - tokens;
310:    cli._hep?.compactionEnd(freed < 0 ? 0 : freed);
311:    _runTokensBefore = null;
