398:List<String> formatCompactionReport(
399:  AutoCompactorPass pass, {
400:  required bool auto,
401:  bool details = false,
402:}) {
403:  final freedRaw = pass.tokensBefore - pass.tokensAfter;
404:  // A restamped estimator can report a slightly larger after-count (same
405:  // clamp as onDone's HEP end frame): "-30 freed" reads as a bug.
406:  final freed = freedRaw < 0 ? 0 : freedRaw;
407:  final pct = pass.tokensBefore == 0
408:      ? 0
409:      : (freed * 100 / pass.tokensBefore).round();
410:  // gh-2097: an upward basis jump renders EXPLICITLY — the pass appended
411:  // only shrinkers, so an after-count above the before-count is the
412:  // session projection holding more than the in-memory view did at
413:  // measurement time (a second writer), not a compaction regression.
