14:  /// LLM completion for host features (the `jsr.fa.llm*` bridge in JS apps).
15:  /// Runs on a throwaway agent with no tools, so it never touches the session
16:  /// transcript. `system` messages are folded into the system prompt; `user`
17:  /// and `assistant` messages become the conversation, which should end with
18:  /// a user message. When [onDelta] is given, streamed text deltas are
19:  /// forwarded as they arrive.
20:  Future<String> completeOnce(
21:    List<FaLlmMessage> messages, {
22:    void Function(String delta)? onDelta,
23:  }) async {
24:    final model = _agent.state.model;
25:    final agent = Agent(
26:      model: model,
27:      systemPrompt: completeOnceSystemPrompt(messages),
28:      streamFunction: _agent.streamFunction,
29:      toolRegistry: ToolRegistry(const []),
30:    );
31:    if (onDelta != null) {
32:      agent.subscribe((event, cancelToken) async {
33:        if (event case MessageUpdateEvent(
34:          assistantMessageEvent: TextDeltaEvent(:final delta),
35:        )) {
36:          onDelta(delta);
37:        }
38:      });
39:    }
40:    final conversation = completeOnceConversation(messages, model);
41:    if (conversation.isEmpty) {
42:      throw StateError('messages must include at least one user message');
43:    }
44:    await agent.promptMessages(conversation);
45:    return completeOnceText(agent.state.messages);
46:  }
