48:  /// Starts one agent run and settles the UI state no matter how it ends.
49:  ///
50:  /// [startRun] is invoked LAZILY inside a try/catch: `Agent.prompt*` throws
51:  /// synchronously when a run is already active, and the composer calls the
52:  /// send methods unawaited — a synchronous escape would surface as an
53:  /// unhandled async error in the console (the "Uncaught Error" storm after
54:  /// a provider failure) instead of the error banner. Timeouts and async
55:  /// failures land in `catchError`, which always re-enables the UI.
56:  void _runWithTimeout(Future<void> Function() startRun) {
57:    final Future<void> run;
58:    try {
59:      // Multi-day sessions: re-compose the prompt so the model sees
60:      // TODAY's date, not the session creation date.
61:      final config = _config;
62:      if (config != null) {
63:        _agent.state.systemPrompt = _composeSystemPrompt(config);
64:      }
65:      _armIdleWatchdog();
66:      run = startRun();
67:    } on Object catch (e) {
68:      _idleWatchdog?.cancel();
69:      isStreaming = false;
70:      error = e is StateError ? e.message : e.toString();
71:      _notify();
72:      return;
73:    }
74:    run.catchError((Object e) {
75:      _idleWatchdog?.cancel();
76:      isStreaming = false;
77:      error = e.toString();
78:      // dispose() aborts an in-flight run — its error lands here after the
79:      // service is gone; notifying a disposed ChangeNotifier throws.
80:      if (_disposed) return;
81:      _notify();
82:    });
83:  }
84:}
