25:  /// Initializes session persistence — WITHOUT creating an empty JSONL file.
26:  ///
27:  /// The session file (and the agent's mailbox address in the messaging
28:  /// fabric) are materialised lazily on the first [_persist] run; a service
29:  /// that is initialised but never receives a user message leaves no file
30:  /// behind. [loadSession] still creates an OS-backed [_session] for the
31:  /// restored session.
32:  Future<void> initialize() async {
33:    // A fresh/cleared session invalidates in-flight loaders (issue #199).
34:    _loadGeneration++;
35:    // The session FILE materialises lazily on the first persist (an
36:    // untouched session never hits the disk), but the id is allocated
37:    // eagerly: hosts (FlutterSessionManager) key sessions by id from the
38:    // moment the service exists, and the prompt's messaging section needs
39:    // the real mailbox address before the first message.
40:    if (_session == null && _sessionId == null) {
41:      final id = createSessionId();
42:      _sessionId = id;
43:      _setMailboxPrefix(id);
44:    }
45:    // Compose the system prompt eagerly — messaging address defaults to the
46:    // host's local id (`main`) until the session materialises (so a brand
47:    // new, no-message service doesn't crash on prompt render).
48:    final config = _config;
49:    if (config != null) {
50:      _agent.state.systemPrompt = _composeSystemPrompt(config);
51:    }
52:    // Best-effort cleanup of legacy empty sessions (no transcript — only the
53:    // JSONL header). Runs in the background so it never slows startup.
54:    unawaited(_cleanupLegacyEmptySessions());
55:    // The watcher only exists with a messaging fabric (production ctor);
56:    // lightweight test services never start a timer.
57:    if (_subagentManager != null) _startInboxWatcher();
58:    // Sleep prevention (issues #325/#326): only the EXPLICIT session
59:    // hold acquires here — the default per-run hold acquires when a run
60:    // goes in flight (the isStreaming bracket), so an idle app never
61:    // pins the machine awake. A failure logs and the session continues.
62:    unawaited(powerAssertion?.onSessionOpened());
63:  }
